insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('a5f8e381-8801-406e-9372-7e0173bfe4e4', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Foundations: Diversity, Identity, and Social Location', 'This opening section establishes a shared vocabulary for studying difference without reducing people to categories. Students learn to connect identity, culture, history, and context to social-work relationships and decisions.', 0),
  ('290115c1-6c86-469d-a8a7-60c34c92c717', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'a5f8e381-8801-406e-9372-7e0173bfe4e4', 'subtopic'::public.curated_course_node_type, 'Diversity and difference', 'Clarifies what diversity includes, why difference is socially meaningful, and how a strengths-based approach avoids treating dominant-group experience as universal.', 0),
  ('50532e0f-3e85-42e1-b0f4-4d87d7ae60b9', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '290115c1-6c86-469d-a8a7-60c34c92c717', 'concept'::public.curated_course_node_type, 'Dimensions of diversity: race, ethnicity, culture, class, gender, sexuality, disability, age, religion, nationality, language, and political belief', null, 0),
  ('a2759d4c-581c-4a72-8b5b-a5ad2c1191bf', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '290115c1-6c86-469d-a8a7-60c34c92c717', 'concept'::public.curated_course_node_type, 'Within-group diversity and the limits of categorical thinking', null, 1),
  ('0f6474ca-290e-4fd9-ab89-aaec1c79b643', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '290115c1-6c86-469d-a8a7-60c34c92c717', 'concept'::public.curated_course_node_type, 'Difference as a source of knowledge, resilience, and collective strength', null, 2),
  ('9b62d514-2b64-4f0b-8c56-f6c76b1fd783', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'a5f8e381-8801-406e-9372-7e0173bfe4e4', 'subtopic'::public.curated_course_node_type, 'Social identity and social location', 'Helps students map how identities are lived within relationships and institutions, including identities that are chosen, assigned, visible, concealed, or changing.', 1),
  ('a2fccfb2-7f1e-4829-9ee4-d21c83659c37', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9b62d514-2b64-4f0b-8c56-f6c76b1fd783', 'concept'::public.curated_course_node_type, 'Personal, relational, collective, and professional identities', null, 0),
  ('de316621-02eb-4cd6-8503-a11b51e3eb4e', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9b62d514-2b64-4f0b-8c56-f6c76b1fd783', 'concept'::public.curated_course_node_type, 'Ascribed and achieved identities; visibility and disclosure', null, 1),
  ('e24af25f-bd68-4b56-b8b3-d2ae8ac72a16', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9b62d514-2b64-4f0b-8c56-f6c76b1fd783', 'concept'::public.curated_course_node_type, 'Context-dependent salience and identity development', null, 2),
  ('13caad86-8f3e-4cf1-ac34-3b43da69a8ea', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'a5f8e381-8801-406e-9372-7e0173bfe4e4', 'subtopic'::public.curated_course_node_type, 'Culture, worldview, and meaning', 'Builds skill in asking how communities make meaning while resisting stereotypes and cultural essentialism.', 2),
  ('19bfcee4-1861-4453-8bb2-e77e4658ea7c', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '13caad86-8f3e-4cf1-ac34-3b43da69a8ea', 'concept'::public.curated_course_node_type, 'Culture as dynamic, contested, and adaptive', null, 0),
  ('71e7f362-2450-427a-bf3a-93ae5ea02b0f', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '13caad86-8f3e-4cf1-ac34-3b43da69a8ea', 'concept'::public.curated_course_node_type, 'Worldviews, values, kinship, spirituality, and healing traditions', null, 1),
  ('b6c4257a-8374-438f-9f93-6e087ecea642', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '13caad86-8f3e-4cf1-ac34-3b43da69a8ea', 'concept'::public.curated_course_node_type, 'Acculturation, biculturalism, code-switching, and cultural continuity', null, 2),
  ('4fb030ef-0aef-4090-b620-3556e5b9116a', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Power, Privilege, Oppression, and Liberation', 'This section supplies the structural lens for the course. Students move beyond prejudice as an individual attitude to examine how power organizes access, risk, voice, and life chances—and how people resist and transform oppressive arrangements.', 1),
  ('ebd6eae8-cd75-4fae-93a9-8d312373b68d', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '4fb030ef-0aef-4090-b620-3556e5b9116a', 'subtopic'::public.curated_course_node_type, 'Power and privilege', 'Shows how power operates through resources, authority, legitimacy, and agenda setting, including benefits that can be unearned and difficult to see from advantaged positions.', 0),
  ('bf65686e-e2c9-4c15-a3b3-43948f11ff44', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ebd6eae8-cd75-4fae-93a9-8d312373b68d', 'concept'::public.curated_course_node_type, 'Power over, power with, power to, and power within', null, 0),
  ('a3caacc3-9933-4678-b1bb-87a3fcc737a3', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ebd6eae8-cd75-4fae-93a9-8d312373b68d', 'concept'::public.curated_course_node_type, 'Unearned advantage, entitlement, and dominant-group norms', null, 1),
  ('7cc4374d-22c4-4acb-b224-ae5990022d62', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ebd6eae8-cd75-4fae-93a9-8d312373b68d', 'concept'::public.curated_course_node_type, 'Gatekeeping, professional authority, and resource control', null, 2),
  ('1c3d4a1e-2f90-4d08-a60e-8a05bebf3269', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '4fb030ef-0aef-4090-b620-3556e5b9116a', 'subtopic'::public.curated_course_node_type, 'Levels and mechanisms of oppression', 'Distinguishes interpersonal harm from institutional and structural patterns so interventions can target the level producing the problem.', 1),
  ('53379122-a070-4574-be6e-3f020a16264e', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '1c3d4a1e-2f90-4d08-a60e-8a05bebf3269', 'concept'::public.curated_course_node_type, 'Internalized, interpersonal, institutional, and structural oppression', null, 0),
  ('a61c602d-137b-46e4-8490-962feb365bcd', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '1c3d4a1e-2f90-4d08-a60e-8a05bebf3269', 'concept'::public.curated_course_node_type, 'Ideology, policy, routine practice, and cumulative disadvantage', null, 1),
  ('c012a8f3-4130-433c-a7b3-311b60a13ac1', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '1c3d4a1e-2f90-4d08-a60e-8a05bebf3269', 'concept'::public.curated_course_node_type, 'Segregation, surveillance, exclusion, extraction, and erasure', null, 2),
  ('814de2d8-7191-4eb1-a537-11b2352dd358', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '4fb030ef-0aef-4090-b620-3556e5b9116a', 'subtopic'::public.curated_course_node_type, 'Resistance and liberation', 'Centers agency and collective action rather than portraying oppressed communities only through harm or deficit.', 2),
  ('3e500eea-06ba-4887-8094-b7f492f8304e', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '814de2d8-7191-4eb1-a537-11b2352dd358', 'concept'::public.curated_course_node_type, 'Everyday resistance, mutual aid, organizing, and movement building', null, 0),
  ('9cb3f8b9-0b36-49ef-8aa2-5a6623e6f546', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '814de2d8-7191-4eb1-a537-11b2352dd358', 'concept'::public.curated_course_node_type, 'Liberatory consciousness and collective efficacy', null, 1),
  ('00b152c4-b588-464c-a3d9-51b35b594f8b', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '814de2d8-7191-4eb1-a537-11b2352dd358', 'concept'::public.curated_course_node_type, 'Restoration, reparation, redistribution, recognition, and representation', null, 2),
  ('453ac892-91c9-45f0-89aa-8df426efab4a', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Intersectionality and Multiple Systems of Inequality', 'Intersectionality helps students analyze how systems of power combine to create experiences that cannot be understood by adding single identities together. It is both an analytic lens and a guide to more precise practice.', 2),
  ('605e5cdc-3fb9-4b8b-8651-c8f730be1cc3', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '453ac892-91c9-45f0-89aa-8df426efab4a', 'subtopic'::public.curated_course_node_type, 'Origins and core claims', 'Introduces the Black feminist roots of intersectionality and its focus on power, institutional failure, and people erased by single-axis frameworks.', 0),
  ('9d45034e-8a0a-4ccc-b5bd-ec7d4f50ed1b', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '605e5cdc-3fb9-4b8b-8651-c8f730be1cc3', 'concept'::public.curated_course_node_type, 'Black feminist thought and the Combahee River Collective', null, 0),
  ('60f5cfed-dfd0-448a-aa17-38fdabaad475', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '605e5cdc-3fb9-4b8b-8651-c8f730be1cc3', 'concept'::public.curated_course_node_type, 'Crenshaw’s structural, political, and representational intersectionality', null, 1),
  ('ffbfd3e8-3aae-48da-9ca7-1dbaa2bbbcaf', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '605e5cdc-3fb9-4b8b-8651-c8f730be1cc3', 'concept'::public.curated_course_node_type, 'Avoiding “identity checklist” versions of intersectionality', null, 2),
  ('93b8e7f8-88cd-455e-86e5-38758899c7c1', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '453ac892-91c9-45f0-89aa-8df426efab4a', 'subtopic'::public.curated_course_node_type, 'Intersecting systems in lived experience', 'Develops contextual analysis of how social locations change exposure to risk, access to services, and treatment by institutions.', 1),
  ('b271f203-37d1-4774-8259-79aac9c18917', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '93b8e7f8-88cd-455e-86e5-38758899c7c1', 'concept'::public.curated_course_node_type, 'Race–class–gender–disability intersections', null, 0),
  ('c4ce6ae0-d24d-4989-ad69-2b45f3734c0e', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '93b8e7f8-88cd-455e-86e5-38758899c7c1', 'concept'::public.curated_course_node_type, 'Cumulative advantage and disadvantage across the life course', null, 1),
  ('8e9a43ed-9feb-4ba8-90ff-e2c168daa1d1', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '93b8e7f8-88cd-455e-86e5-38758899c7c1', 'concept'::public.curated_course_node_type, 'Within-group differences and intragroup power', null, 2),
  ('680ab2cd-92d2-4259-bc65-985c6b2ca3dc', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '453ac892-91c9-45f0-89aa-8df426efab4a', 'subtopic'::public.curated_course_node_type, 'Intersectional assessment and policy analysis', 'Translates theory into questions, data practices, and policy evaluation that reveal who benefits, who is burdened, and who is missing.', 2),
  ('13b0ff64-c97d-4df1-885b-73045173fc02', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '680ab2cd-92d2-4259-bc65-985c6b2ca3dc', 'concept'::public.curated_course_node_type, 'Disaggregated and community-defined data', null, 0),
  ('75479a13-92ba-41de-8007-3f631330afc7', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '680ab2cd-92d2-4259-bc65-985c6b2ca3dc', 'concept'::public.curated_course_node_type, 'Universal design versus targeted universalism', null, 1),
  ('7589cc7c-1e6e-46c9-b0a8-70318ef44882', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '680ab2cd-92d2-4259-bc65-985c6b2ca3dc', 'concept'::public.curated_course_node_type, 'Unintended consequences and distributional impact', null, 2),
  ('ed4565d8-47a1-481f-9925-e7808ccb59ae', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Racism, Racialization, Colonialism, and Indigenous Sovereignty', 'This section examines racism as a historical and contemporary system, not merely personal bias. It also addresses settler colonialism and Indigenous rights so anti-racist practice includes sovereignty, land, and self-determination.', 3);
