  ('04401c41-aaf8-473c-a1fb-3f16b178ab14', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'f0c95517-08e8-4502-ae92-910f511d85fd', 'concept'::public.curated_course_node_type, 'Disparity, disproportionality, discrimination, and causal inference', null, 2),
  ('0eb7f8d2-cf67-421a-a918-7e0e3b073a8a', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ed4565d8-47a1-481f-9925-e7808ccb59ae', 'subtopic'::public.curated_course_node_type, 'Settler colonialism and Indigenous sovereignty', 'Builds respect for Indigenous peoples as contemporary political communities with inherent rights, knowledge systems, and authority.', 2),
  ('d5d079bc-93b0-42a3-8940-4cd9e356d213', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '0eb7f8d2-cf67-421a-a918-7e0e3b073a8a', 'concept'::public.curated_course_node_type, 'Land, treaties, sovereignty, and self-determination', null, 0),
