  ('165510ad-f841-47b5-a8c7-5addc7e18e1e', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ed4565d8-47a1-481f-9925-e7808ccb59ae', 'subtopic'::public.curated_course_node_type, 'Anti-racist and decolonizing practice', 'Moves from awareness to accountable action in relationships, organizations, policy, and research.', 3),
  ('9382be6a-69f4-4b59-9438-91d837e124a9', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '165510ad-f841-47b5-a8c7-5addc7e18e1e', 'concept'::public.curated_course_node_type, 'Racial equity impact assessment', null, 0),
  ('42714683-872c-4992-ae33-2ac606ba54fc', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '165510ad-f841-47b5-a8c7-5addc7e18e1e', 'concept'::public.curated_course_node_type, 'Power sharing, reparative approaches, and institutional accountability', null, 1),
  ('66a12574-8896-4016-a6c3-062fc294a8cb', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '165510ad-f841-47b5-a8c7-5addc7e18e1e', 'concept'::public.curated_course_node_type, 'Community-defined evidence and Indigenous data sovereignty', null, 2),
  ('40429b5c-7341-4082-959a-9c3e8e001728', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Sexism, Patriarchy, and Gender Justice', 'Students investigate how gender is socially organized and how sexism interacts with race, class, disability, sexuality, and nationality. The focus is gender justice in everyday practice and institutions.', 4),
  ('36cfc7d2-2829-4fda-9abe-f8a1a23ed06f', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '40429b5c-7341-4082-959a-9c3e8e001728', 'subtopic'::public.curated_course_node_type, 'Gender as a social system', 'Separates sex characteristics, gender identity, gender expression, and social roles while examining how institutions enforce gender norms.', 0),
  ('f5dc6a7a-bf92-49c0-85bf-2403736ddeaf', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '36cfc7d2-2829-4fda-9abe-f8a1a23ed06f', 'concept'::public.curated_course_node_type, 'Gender socialization and the gender binary', null, 0),
  ('78054c05-8a05-43fb-82fc-f656ec5ae269', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '36cfc7d2-2829-4fda-9abe-f8a1a23ed06f', 'concept'::public.curated_course_node_type, 'Patriarchy, cisnormativity, and hegemonic masculinity', null, 1),
  ('4f84c2c8-20a3-4dc3-a74e-324184acb0da', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '36cfc7d2-2829-4fda-9abe-f8a1a23ed06f', 'concept'::public.curated_course_node_type, 'Gender diversity across cultures and histories', null, 2),
  ('501894c6-d5cd-40df-baca-c5b07d8424a0', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '40429b5c-7341-4082-959a-9c3e8e001728', 'subtopic'::public.curated_course_node_type, 'Gendered inequality and violence', 'Connects private experience to structural conditions and highlights survivor-centered, non-carceral possibilities.', 1),
