  ('e8bbf2b5-0111-4e49-a4c1-719ce47adfa8', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '3d1e1fea-b264-4884-8521-81f6d63fa4fd', 'subtopic'::public.curated_course_node_type, 'Xenophobia and legal precarity', 'Shows how status and national-origin hierarchies influence safety, eligibility, work, health, and surveillance.', 1),
  ('ffc53b18-0a59-4dc3-bd9b-d8a6738a8ccb', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'e8bbf2b5-0111-4e49-a4c1-719ce47adfa8', 'concept'::public.curated_course_node_type, 'Citizenship privilege, nativism, detention, and deportability', null, 0),
