  ('0ad47ca9-1701-4fbe-8181-1b79c9d45dfe', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '3d1e1fea-b264-4884-8521-81f6d63fa4fd', 'subtopic'::public.curated_course_node_type, 'Language justice and responsive practice', 'Treats communication access as a right and language diversity as an asset.', 2),
  ('d274c749-8cf4-4e46-bc8b-8eac33978231', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '0ad47ca9-1701-4fbe-8181-1b79c9d45dfe', 'concept'::public.curated_course_node_type, 'Professional interpretation and translated materials', null, 0),
  ('26dad3f2-d0c7-4543-8b44-fd15a8dd42d2', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '0ad47ca9-1701-4fbe-8181-1b79c9d45dfe', 'concept'::public.curated_course_node_type, 'Linguicism, accent bias, and literacy', null, 1),
  ('089a9bf9-c443-4b91-99b7-3e4ccce12b2a', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '0ad47ca9-1701-4fbe-8181-1b79c9d45dfe', 'concept'::public.curated_course_node_type, 'Culturally responsive, trauma-informed, and community-partnered services', null, 2),
  ('0765a030-16e0-4ced-9592-a65d24f0fdb0', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Ageism and Justice Across the Life Course', 'Students analyze how age-based power affects children, youth, adults, and older people. A life-course lens connects present conditions to historical timing, transitions, and accumulated advantage or disadvantage.', 10),
  ('4703b665-1be2-41a5-8328-56805422dd54', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '0765a030-16e0-4ced-9592-a65d24f0fdb0', 'subtopic'::public.curated_course_node_type, 'Ageism and adultism', 'Makes visible age-based stereotypes and the unequal authority attached to adulthood, youth, and later life.', 0),
  ('e2fddbf7-2e4b-4e47-b957-f3faa8a9d5b4', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '4703b665-1be2-41a5-8328-56805422dd54', 'concept'::public.curated_course_node_type, 'Adultism and children’s participation rights', null, 0),
  ('33d25b28-0367-4fb5-80e6-46ba7c90ebc9', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '4703b665-1be2-41a5-8328-56805422dd54', 'concept'::public.curated_course_node_type, 'Ageism in work, health care, media, and social services', null, 1),
  ('f297ebfc-9f52-4eb2-80ff-8c3dbe7ffd64', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '4703b665-1be2-41a5-8328-56805422dd54', 'concept'::public.curated_course_node_type, 'Age norms, dependency narratives, and intergenerational tension', null, 2),
  ('9fb19701-8de1-4d25-a2b2-9f1a2c6f98eb', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '0765a030-16e0-4ced-9592-a65d24f0fdb0', 'subtopic'::public.curated_course_node_type, 'Life-course and cohort perspectives', 'Helps students interpret development in social and historical context rather than treating age as a universal experience.', 1),
  ('8d3b972a-aa0d-46cf-9c65-96ec8a6b4744', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9fb19701-8de1-4d25-a2b2-9f1a2c6f98eb', 'concept'::public.curated_course_node_type, 'Cohort, period, and life-stage effects', null, 0),
  ('f16ccb48-c557-45d4-9e84-d44764d3933a', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9fb19701-8de1-4d25-a2b2-9f1a2c6f98eb', 'concept'::public.curated_course_node_type, 'Transitions, turning points, linked lives, and cumulative inequality', null, 1),
  ('7f7abfb2-12e5-406e-80b3-6371f1ff9c94', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9fb19701-8de1-4d25-a2b2-9f1a2c6f98eb', 'concept'::public.curated_course_node_type, 'Longevity, caregiving, retirement, and changing family forms', null, 2),
  ('8747c43b-fbd5-43ef-8e04-27de2a61bdf6', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '0765a030-16e0-4ced-9592-a65d24f0fdb0', 'subtopic'::public.curated_course_node_type, 'Age-inclusive practice', 'Builds capacity to balance protection, participation, autonomy, and relational care.', 2),
  ('7ef634a3-6512-4196-b012-d003a8c1faf6', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '8747c43b-fbd5-43ef-8e04-27de2a61bdf6', 'concept'::public.curated_course_node_type, 'Supported decision-making and capacity', null, 0),
  ('76f69a56-5dc7-4498-bd03-66d7ea577ffe', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '8747c43b-fbd5-43ef-8e04-27de2a61bdf6', 'concept'::public.curated_course_node_type, 'Child/youth participation and elder self-determination', null, 1),
  ('d1197eda-2122-4698-b385-17c106c21c82', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '8747c43b-fbd5-43ef-8e04-27de2a61bdf6', 'concept'::public.curated_course_node_type, 'Intergenerational programs and age-friendly communities', null, 2),
  ('e8fca8f6-5614-4958-bb01-9dc3363a4869', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Environmental, Spatial, and Digital Justice', 'Justice increasingly depends on where people live and whether they can access safe environments and essential technologies. This section connects ecological, geographic, and digital conditions to social-work practice.', 11),
  ('a7d77938-5b77-4497-88a0-993b28ee9604', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'e8fca8f6-5614-4958-bb01-9dc3363a4869', 'subtopic'::public.curated_course_node_type, 'Environmental and climate justice', 'Shows why environmental hazards and climate impacts are distributed through race, class, colonialism, and political power.', 0),
  ('29441afb-ddac-4b54-9302-7252a3a0d79f', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'a7d77938-5b77-4497-88a0-993b28ee9604', 'concept'::public.curated_course_node_type, 'Environmental racism and cumulative exposure', null, 0),
  ('1beaa66d-3789-4afe-a10e-2c6188557075', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'a7d77938-5b77-4497-88a0-993b28ee9604', 'concept'::public.curated_course_node_type, 'Climate disasters, heat, food/water insecurity, and displacement', null, 1),
  ('70624e0b-94a1-4efa-87b2-5df6630afe5a', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'a7d77938-5b77-4497-88a0-993b28ee9604', 'concept'::public.curated_course_node_type, 'Just transition, energy justice, and Indigenous environmental stewardship', null, 2),
  ('9327262e-fff8-44c8-8ab3-c4f05e0d3b05', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'e8fca8f6-5614-4958-bb01-9dc3363a4869', 'subtopic'::public.curated_course_node_type, 'Place and spatial inequality', 'Examines how geography structures services, mobility, belonging, and opportunity.', 1),
  ('de7da2c1-4a4c-4d9b-a9b1-b71d75fb9188', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9327262e-fff8-44c8-8ab3-c4f05e0d3b05', 'concept'::public.curated_course_node_type, 'Urban, rural, remote, reservation, and border contexts', null, 0),
  ('f8d94f08-ff8e-431c-8548-d0d37af16344', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9327262e-fff8-44c8-8ab3-c4f05e0d3b05', 'concept'::public.curated_course_node_type, 'Housing segregation, transportation, food access, and service deserts', null, 1),
  ('a5e7acee-f991-4f14-85b4-f32987f5b26d', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9327262e-fff8-44c8-8ab3-c4f05e0d3b05', 'concept'::public.curated_course_node_type, 'Gentrification, displacement, carcerality, and public space', null, 2),
  ('962bad18-9c8b-45eb-aa00-98510855b990', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'e8fca8f6-5614-4958-bb01-9dc3363a4869', 'subtopic'::public.curated_course_node_type, 'Digital inequality and algorithmic oppression', 'Prepares students to assess both access barriers and harms created by data-driven systems.', 2),
  ('d8545818-cfe5-40c4-8bd8-b8e61c7a25c3', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '962bad18-9c8b-45eb-aa00-98510855b990', 'concept'::public.curated_course_node_type, 'Devices, connectivity, affordability, accessibility, and digital literacy', null, 0),
  ('ba8c3c92-2c36-447a-b524-24cbfd4bd451', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '962bad18-9c8b-45eb-aa00-98510855b990', 'concept'::public.curated_course_node_type, 'Automated eligibility, risk scoring, facial recognition, and bias', null, 1),
  ('a233aec4-0bd2-47d8-b3ef-f2a12b5560ea', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '962bad18-9c8b-45eb-aa00-98510855b990', 'concept'::public.curated_course_node_type, 'Privacy, surveillance, data rights, and technology-mediated practice', null, 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('117e7037-dc0c-4b9b-8698-70f06c91c88e', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Cultural Humility, Critical Reflexivity, and Ethical Use of Self', 'This section turns inward without making social justice merely personal. Students examine how their social location, emotions, knowledge, and professional authority shape relationships and decisions.', 12),
  ('8cb59747-d528-4223-aa62-1a7dbd6a3c23', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '117e7037-dc0c-4b9b-8698-70f06c91c88e', 'subtopic'::public.curated_course_node_type, 'Cultural humility', 'Frames learning as lifelong self-evaluation and power balancing rather than mastery of other people’s cultures.', 0),
  ('0997666a-0e5e-41b3-bedf-876fa6df97da', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '8cb59747-d528-4223-aa62-1a7dbd6a3c23', 'concept'::public.curated_course_node_type, 'Lifelong learning and self-critique', null, 0),
  ('5f9e4b31-f0cc-450a-a12a-df07044bff80', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '8cb59747-d528-4223-aa62-1a7dbd6a3c23', 'concept'::public.curated_course_node_type, 'Redressing power imbalances', null, 1),
  ('92d19531-ece0-4a92-abc0-62f6d1b51441', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '8cb59747-d528-4223-aa62-1a7dbd6a3c23', 'concept'::public.curated_course_node_type, 'Institutional accountability and mutually beneficial partnership', null, 2),
  ('9f930555-5f0e-4dfe-bc2a-8a9bf1251909', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '117e7037-dc0c-4b9b-8698-70f06c91c88e', 'subtopic'::public.curated_course_node_type, 'Positionality and critical reflexivity', 'Develops disciplined reflection on how standpoint, assumptions, and institutional roles affect what practitioners notice and do.', 1),
  ('1bee07d1-4e50-4caf-8af6-71c4efc6231a', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9f930555-5f0e-4dfe-bc2a-8a9bf1251909', 'concept'::public.curated_course_node_type, 'Positionality statements and social-location mapping', null, 0),
  ('8c40d073-6e64-4cc3-8584-982593f59094', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9f930555-5f0e-4dfe-bc2a-8a9bf1251909', 'concept'::public.curated_course_node_type, 'Bias, defensiveness, shame, guilt, fragility, and moral courage', null, 1),
  ('17974749-8de8-4b00-8242-7585234b8521', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '9f930555-5f0e-4dfe-bc2a-8a9bf1251909', 'concept'::public.curated_course_node_type, 'Countertransference, use of self, and reflective supervision', null, 2),
  ('ed2e8094-d741-4cd5-be06-e53ba36dbbcf', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '117e7037-dc0c-4b9b-8698-70f06c91c88e', 'subtopic'::public.curated_course_node_type, 'Ethics, boundaries, and epistemic justice', 'Connects humility to professional obligations around consent, authority, confidentiality, and whose knowledge counts.', 2),
  ('a2de91f9-cee6-4162-99ac-a65384fc5dde', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ed2e8094-d741-4cd5-be06-e53ba36dbbcf', 'concept'::public.curated_course_node_type, 'Self-determination, informed consent, privacy, and mandated authority', null, 0),
  ('9ee3a038-bf8a-4b16-be2c-ee37ae5c2df2', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ed2e8094-d741-4cd5-be06-e53ba36dbbcf', 'concept'::public.curated_course_node_type, 'Testimonial and hermeneutical injustice', null, 1),
  ('adf56a0e-4151-4034-a84a-fdf2526e3c14', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ed2e8094-d741-4cd5-be06-e53ba36dbbcf', 'concept'::public.curated_course_node_type, 'Ethical tensions, accountability, repair, and professional self-care', null, 2),
  ('a0baefca-662c-4f86-9a23-905612a61142', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', null, 'topic'::public.curated_course_node_type, 'Anti-Oppressive Practice, Solidarity, and Social Change', 'The final section integrates course learning into action at micro, mezzo, and macro levels. Students learn to work with—not simply for—people affected by injustice and to evaluate whether change efforts redistribute power.', 13),
  ('ac56bb53-c6c8-4b09-b389-c91c7594aeb6', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'a0baefca-662c-4f86-9a23-905612a61142', 'subtopic'::public.curated_course_node_type, 'Anti-oppressive and rights-based practice', 'Provides frameworks for linking immediate needs to structural causes while preserving dignity, choice, and accountability.', 0),
  ('c8fbf24f-c98d-4a26-ba39-5f40865448cb', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ac56bb53-c6c8-4b09-b389-c91c7594aeb6', 'concept'::public.curated_course_node_type, 'Anti-oppressive, structural, critical, feminist, and human-rights approaches', null, 0),
  ('44bee710-b70e-4c16-b796-8f03cbf9acdf', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ac56bb53-c6c8-4b09-b389-c91c7594aeb6', 'concept'::public.curated_course_node_type, 'Strengths, empowerment, healing-centered, and trauma-responsive practice', null, 1),
  ('54a23eac-30b3-4d65-84d6-68022ee1d572', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'ac56bb53-c6c8-4b09-b389-c91c7594aeb6', 'concept'::public.curated_course_node_type, 'Micro–mezzo–macro integration and person-in-environment analysis', null, 2),
  ('84edc38f-95db-441d-a9ef-58a0c31ed494', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'a0baefca-662c-4f86-9a23-905612a61142', 'subtopic'::public.curated_course_node_type, 'Allyship, solidarity, and accountable partnership', 'Distinguishes identity claims from sustained practices that accept guidance, risk, correction, and responsibility.', 1),
  ('09fdfa54-03f3-4f6b-a943-5b14d3917db5', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '84edc38f-95db-441d-a9ef-58a0c31ed494', 'concept'::public.curated_course_node_type, 'Allyship versus performativity; accompliceship and solidarity', null, 0),
  ('7b677a88-2615-44f4-ba32-75ddeca6ba85', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '84edc38f-95db-441d-a9ef-58a0c31ed494', 'concept'::public.curated_course_node_type, 'Centering lived expertise and compensating community knowledge', null, 1),
  ('ef02d7ce-78fd-4936-b5c5-c74ec780871f', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '84edc38f-95db-441d-a9ef-58a0c31ed494', 'concept'::public.curated_course_node_type, 'Coalition building, conflict, accountability, and repair', null, 2),
  ('524f7f9c-4225-4471-b715-e0e801da3440', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', 'a0baefca-662c-4f86-9a23-905612a61142', 'subtopic'::public.curated_course_node_type, 'Advocacy and policy practice', 'Equips students to choose strategies matched to power, targets, evidence, and community priorities.', 2),
  ('4b61e529-1a19-4941-95ef-a7a92537ee48', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '524f7f9c-4225-4471-b715-e0e801da3440', 'concept'::public.curated_course_node_type, 'Power mapping, stakeholder analysis, and theory of change', null, 0),
  ('5b1c7f5f-80d7-4042-9985-80aef222788b', 'f3a4b5c6-8d9e-4f63-8a23-3b4c5d6e7f33', '524f7f9c-4225-4471-b715-e0e801da3440', 'concept'::public.curated_course_node_type, 'Direct action, legislative advocacy, administrative advocacy, litigation, and communications', null, 1),
