  'diversity-oppression-and-social-justice',
  null,
  'Diversity, Oppression, and Social Justice',
  'Diversity, Oppression, and Social Justice',
  'This course examines diversity, power, privilege, oppression, resistance, and liberation as central concerns of generalist social work. Using intersectional, anti-racist, anti-oppressive, decolonizing, disability-justice, feminist, queer, human-rights, and environmental-justice lenses, students analyze how identities and social locations are shaped by institutions, histories, policies, and everyday relationships. Through critical reflection, case analysis, dialogue, community knowledge, and applied advocacy, students build the humility and practical skill to engage difference, challenge injustice, share power, and pursue accountable change with individuals, families, groups, organizations, and communities.',
  $dosjjson${"slug": "diversity-oppression-and-social-justice", "title": "Diversity, Oppression, and Social Justice", "description": "This course examines diversity, power, privilege, oppression, resistance, and liberation as central concerns of generalist social work. Using intersectional, anti-racist, anti-oppressive, decolonizing, disability-justice, feminist, queer, human-rights, and environmental-justice lenses, students analyze how identities and social locations are shaped by institutions, histories, policies, and everyday relationships. Through critical reflection, case analysis, dialogue, community knowledge, and applied advocacy, students build the humility and practical skill to engage difference, challenge injustice, share power, and pursue accountable change with individuals, families, groups, organizations, and communities.", "topics": [{"id": "a5f8e381-8801-406e-9372-7e0173bfe4e4", "type": "topic", "title": "Foundations: Diversity, Identity, and Social Location", "description": "This opening section establishes a shared vocabulary for studying difference without reducing people to categories. Students learn to connect identity, culture, history, and context to social-work relationships and decisions.", "children": [{"id": "290115c1-6c86-469d-a8a7-60c34c92c717", "type": "subtopic", "title": "Diversity and difference", "children": [{"id": "50532e0f-3e85-42e1-b0f4-4d87d7ae60b9", "type": "concept", "title": "Dimensions of diversity: race, ethnicity, culture, class, gender, sexuality, disability, age, religion, nationality, language, and political belief"}, {"id": "a2759d4c-581c-4a72-8b5b-a5ad2c1191bf", "type": "concept", "title": "Within-group diversity and the limits of categorical thinking"}, {"id": "0f6474ca-290e-4fd9-ab89-aaec1c79b643", "type": "concept", "title": "Difference as a source of knowledge, resilience, and collective strength"}], "description": "Clarifies what diversity includes, why difference is socially meaningful, and how a strengths-based approach avoids treating dominant-group experience as universal."}, {"id": "9b62d514-2b64-4f0b-8c56-f6c76b1fd783", "type": "subtopic", "title": "Social identity and social location", "children": [{"id": "a2fccfb2-7f1e-4829-9ee4-d21c83659c37", "type": "concept", "title": "Personal, relational, collective, and professional identities"}, {"id": "de316621-02eb-4cd6-8503-a11b51e3eb4e", "type": "concept", "title": "Ascribed and achieved identities; visibility and disclosure"}, {"id": "e24af25f-bd68-4b56-b8b3-d2ae8ac72a16", "type": "concept", "title": "Context-dependent salience and identity development"}], "description": "Helps students map how identities are lived within relationships and institutions, including identities that are chosen, assigned, visible, concealed, or changing."}, {"id": "13caad86-8f3e-4cf1-ac34-3b43da69a8ea", "type": "subtopic", "title": "Culture, worldview, and meaning", "children": [{"id": "19bfcee4-1861-4453-8bb2-e77e4658ea7c", "type": "concept", "title": "Culture as dynamic, contested, and adaptive"}, {"id": "71e7f362-2450-427a-bf3a-93ae5ea02b0f", "type": "concept", "title": "Worldviews, values, kinship, spirituality, and healing traditions"}, {"id": "b6c4257a-8374-438f-9f93-6e087ecea642", "type": "concept", "title": "Acculturation, biculturalism, code-switching, and cultural continuity"}], "description": "Builds skill in asking how communities make meaning while resisting stereotypes and cultural essentialism."}]}, {"id": "4fb030ef-0aef-4090-b620-3556e5b9116a", "type": "topic", "title": "Power, Privilege, Oppression, and Liberation", "description": "This section supplies the structural lens for the course. Students move beyond prejudice as an individual attitude to examine how power organizes access, risk, voice, and life chances—and how people resist and transform oppressive arrangements.", "children": [{"id": "ebd6eae8-cd75-4fae-93a9-8d312373b68d", "type": "subtopic", "title": "Power and privilege", "children": [{"id": "bf65686e-e2c9-4c15-a3b3-43948f11ff44", "type": "concept", "title": "Power over, power with, power to, and power within"}, {"id": "a3caacc3-9933-4678-b1bb-87a3fcc737a3", "type": "concept", "title": "Unearned advantage, entitlement, and dominant-group norms"}, {"id": "7cc4374d-22c4-4acb-b224-ae5990022d62", "type": "concept", "title": "Gatekeeping, professional authority, and resource control"}], "description": "Shows how power operates through resources, authority, legitimacy, and agenda setting, including benefits that can be unearned and difficult to see from advantaged positions."}, {"id": "1c3d4a1e-2f90-4d08-a60e-8a05bebf3269", "type": "subtopic", "title": "Levels and mechanisms of oppression", "children": [{"id": "53379122-a070-4574-be6e-3f020a16264e", "type": "concept", "title": "Internalized, interpersonal, institutional, and structural oppression"}, {"id": "a61c602d-137b-46e4-8490-962feb365bcd", "type": "concept", "title": "Ideology, policy, routine practice, and cumulative disadvantage"}, {"id": "c012a8f3-4130-433c-a7b3-311b60a13ac1", "type": "concept", "title": "Segregation, surveillance, exclusion, extraction, and erasure"}], "description": "Distinguishes interpersonal harm from institutional and structural patterns so interventions can target the level producing the problem."}, {"id": "814de2d8-7191-4eb1-a537-11b2352dd358", "type": "subtopic", "title": "Resistance and liberation", "children": [{"id": "3e500eea-06ba-4887-8094-b7f492f8304e", "type": "concept", "title": "Everyday resistance, mutual aid, organizing, and movement building"}, {"id": "9cb3f8b9-0b36-49ef-8aa2-5a6623e6f546", "type": "concept", "title": "Liberatory consciousness and collective efficacy"}, {"id": "00b152c4-b588-464c-a3d9-51b35b594f8b", "type": "concept", "title": "Restoration, reparation, redistribution, recognition, and representation"}], "description": "Centers agency and collective action rather than portraying oppressed communities only through harm or deficit."}]}, {"id": "453ac892-91c9-45f0-89aa-8df426efab4a", "type": "topic", "title": "Intersectionality and Multiple Systems of Inequality", "description": "Intersectionality helps students analyze how systems of power combine to create experiences that cannot be understood by adding single identities together. It is both an analytic lens and a guide to more precise practice.", "children": [{"id": "605e5cdc-3fb9-4b8b-8651-c8f730be1cc3", "type": "subtopic", "title": "Origins and core claims", "children": [{"id": "9d45034e-8a0a-4ccc-b5bd-ec7d4f50ed1b", "type": "concept", "title": "Black feminist thought and the Combahee River Collective"}, {"id": "60f5cfed-dfd0-448a-aa17-38fdabaad475", "type": "concept", "title": "Crenshaw’s structural, political, and representational intersectionality"}, {"id": "ffbfd3e8-3aae-48da-9ca7-1dbaa2bbbcaf", "type": "concept", "title": "Avoiding “identity checklist” versions of intersectionality"}], "description": "Introduces the Black feminist roots of intersectionality and its focus on power, institutional failure, and people erased by single-axis frameworks."}, {"id": "93b8e7f8-88cd-455e-86e5-38758899c7c1", "type": "subtopic", "title": "Intersecting systems in lived experience", "children": [{"id": "b271f203-37d1-4774-8259-79aac9c18917", "type": "concept", "title": "Race–class–gender–disability intersections"}, {"id": "c4ce6ae0-d24d-4989-ad69-2b45f3734c0e", "type": "concept", "title": "Cumulative advantage and disadvantage across the life course"}, {"id": "8e9a43ed-9feb-4ba8-90ff-e2c168daa1d1", "type": "concept", "title": "Within-group differences and intragroup power"}], "description": "Develops contextual analysis of how social locations change exposure to risk, access to services, and treatment by institutions."}, {"id": "680ab2cd-92d2-4259-bc65-985c6b2ca3dc", "type": "subtopic", "title": "Intersectional assessment and policy analysis", "children": [{"id": "13b0ff64-c97d-4df1-885b-73045173fc02", "type": "concept", "title": "Disaggregated and community-defined data"}, {"id": "75479a13-92ba-41de-8007-3f631330afc7", "type": "concept", "title": "Universal design versus targeted universalism"}, {"id": "7589cc7c-1e6e-46c9-b0a8-70318ef44882", "type": "concept", "title": "Unintended consequences and distributional impact"}], "description": "Translates theory into questions, data practices, and policy evaluation that reveal who benefits, who is burdened, and who is missing."}]}, {"id": "ed4565d8-47a1-481f-9925-e7808ccb59ae", "type": "topic", "title": "Racism, Racialization, Colonialism, and Indigenous Sovereignty", "description": "This section examines racism as a historical and contemporary system, not merely personal bias. It also addresses settler colonialism and Indigenous rights so anti-racist practice includes sovereignty, land, and self-determination.", "children": [{"id": "0c8c11b1-2032-42bf-bb30-ac2b31faa602", "type": "subtopic", "title": "Race and racialization", "children": [{"id": "0f80ee21-9d02-43f7-98ec-54881cd2e335", "type": "concept", "title": "Social construction of race and racial formation"}, {"id": "4770fb1d-dded-4aa9-a87b-afaea5f6d510", "type": "concept", "title": "Whiteness, colorism, anti-Blackness, and model-minority narratives"}, {"id": "8d717791-1259-4273-be6f-806fcd0e5487", "type": "concept", "title": "Implicit bias, explicit bias, microaggressions, and racial trauma"}], "description": "Explains race as a changing social and political classification with material consequences."}, {"id": "f0c95517-08e8-4502-ae92-910f511d85fd", "type": "subtopic", "title": "Structural and institutional racism", "children": [{"id": "c2f660e2-a67b-4b73-905a-f91006c37e21", "type": "concept", "title": "Housing, education, health, child welfare, immigration, and criminal legal systems"}, {"id": "6c91cc77-620c-4e56-926a-5556fda8d839", "type": "concept", "title": "Redlining, segregation, wealth extraction, and cumulative harm"}, {"id": "04401c41-aaf8-473c-a1fb-3f16b178ab14", "type": "concept", "title": "Disparity, disproportionality, discrimination, and causal inference"}], "description": "Links historical policies to current disparities without treating inequity as proof of group deficiency."}, {"id": "0eb7f8d2-cf67-421a-a918-7e0e3b073a8a", "type": "subtopic", "title": "Settler colonialism and Indigenous sovereignty", "children": [{"id": "d5d079bc-93b0-42a3-8940-4cd9e356d213", "type": "concept", "title": "Land, treaties, sovereignty, and self-determination"}, {"id": "446d7d89-ba41-4273-bf2b-53dd35153b10", "type": "concept", "title": "Forced removal, residential/boarding schools, child removal, and cultural suppression"}, {"id": "da7b1492-729f-47ef-b5c3-a4054d4d7836", "type": "concept", "title": "Decolonizing practice, rematriation, and community-led healing"}], "description": "Builds respect for Indigenous peoples as contemporary political communities with inherent rights, knowledge systems, and authority."}, {"id": "165510ad-f841-47b5-a8c7-5addc7e18e1e", "type": "subtopic", "title": "Anti-racist and decolonizing practice", "children": [{"id": "9382be6a-69f4-4b59-9438-91d837e124a9", "type": "concept", "title": "Racial equity impact assessment"}, {"id": "42714683-872c-4992-ae33-2ac606ba54fc", "type": "concept", "title": "Power sharing, reparative approaches, and institutional accountability"}, {"id": "66a12574-8896-4016-a6c3-062fc294a8cb", "type": "concept", "title": "Community-defined evidence and Indigenous data sovereignty"}], "description": "Moves from awareness to accountable action in relationships, organizations, policy, and research."}]}, {"id": "40429b5c-7341-4082-959a-9c3e8e001728", "type": "topic", "title": "Sexism, Patriarchy, and Gender Justice", "description": "Students investigate how gender is socially organized and how sexism interacts with race, class, disability, sexuality, and nationality. The focus is gender justice in everyday practice and institutions.", "children": [{"id": "36cfc7d2-2829-4fda-9abe-f8a1a23ed06f", "type": "subtopic", "title": "Gender as a social system", "children": [{"id": "f5dc6a7a-bf92-49c0-85bf-2403736ddeaf", "type": "concept", "title": "Gender socialization and the gender binary"}, {"id": "78054c05-8a05-43fb-82fc-f656ec5ae269", "type": "concept", "title": "Patriarchy, cisnormativity, and hegemonic masculinity"}, {"id": "4f84c2c8-20a3-4dc3-a74e-324184acb0da", "type": "concept", "title": "Gender diversity across cultures and histories"}], "description": "Separates sex characteristics, gender identity, gender expression, and social roles while examining how institutions enforce gender norms."}, {"id": "501894c6-d5cd-40df-baca-c5b07d8424a0", "type": "subtopic", "title": "Gendered inequality and violence", "children": [{"id": "d611c149-3dcc-4beb-a4f6-e7a955eb3e4c", "type": "concept", "title": "Paid work, unpaid care, occupational segregation, and economic insecurity"}, {"id": "98ad1cb8-c838-458f-8df9-4a1f64f232ef", "type": "concept", "title": "Reproductive justice and bodily autonomy"}, {"id": "882db92e-6b87-4a57-822a-b6e897dce19c", "type": "concept", "title": "Gender-based violence, coercive control, and institutional betrayal"}], "description": "Connects private experience to structural conditions and highlights survivor-centered, non-carceral possibilities."}, {"id": "500002eb-b61b-4635-9523-d60e429110c9", "type": "subtopic", "title": "Gender-responsive practice", "children": [{"id": "e8ede4eb-8983-4be0-8359-72c12ac3cdec", "type": "concept", "title": "Survivor-centered and trauma-informed engagement"}, {"id": "7c23b96b-a07c-4374-b927-20311f0a3f8a", "type": "concept", "title": "Inclusive assessment and documentation"}, {"id": "aca20ab4-7f64-4106-9fa6-a59733a33823", "type": "concept", "title": "Policy advocacy for care, safety, pay equity, and reproductive freedom"}], "description": "Develops approaches that affirm agency, safety, and self-definition without stereotyping clients."}]}, {"id": "f816501b-7900-4a39-96fd-5ba0a479811c", "type": "topic", "title": "Sexuality, Gender Diversity, and LGBTQIA2S+ Justice", "description": "This section prepares students to challenge heterosexism and cisnormativity while providing affirming, developmentally appropriate, and context-sensitive support across the life course.", "children": [{"id": "13c96aef-369e-41aa-94cc-8c455c475193", "type": "subtopic", "title": "Sexual orientation and gender diversity", "children": [{"id": "bec113fb-f760-4065-b2f2-0cf87c1df2eb", "type": "concept", "title": "Sexual orientation, romantic orientation, gender identity, expression, and sex characteristics"}, {"id": "f614a60e-e280-4a10-a3bb-2b0b2d505e9a", "type": "concept", "title": "LGBTQIA2S+ histories and community diversity"}, {"id": "e8f65ce6-aeeb-4ff4-9bd5-7a8033f3980b", "type": "concept", "title": "Coming out, disclosure, privacy, and safety"}], "description": "Provides accurate language while emphasizing that terminology, identity, and community membership are culturally and historically situated."}, {"id": "e400c28e-86a9-4bea-bb8d-f21bdfd5804c", "type": "subtopic", "title": "Heterosexism, cisnormativity, and minority stress", "children": [{"id": "b3d8fc9f-3b7e-4eb6-b6b9-367f3806e9bc", "type": "concept", "title": "Interpersonal, institutional, and structural stigma"}, {"id": "c7b91556-6336-4f6b-b7ff-29d5461ab51c", "type": "concept", "title": "Minority stress, rejection, concealment, and resilience"}, {"id": "7546f7df-c7b1-499d-a8f6-670a1aaae664", "type": "concept", "title": "Conversion practices, criminalization, and barriers to care"}], "description": "Explains how stigma and hostile environments shape health and social outcomes without pathologizing identity."}, {"id": "7b6049dd-5f36-479a-8727-3ae971c2c90f", "type": "subtopic", "title": "Affirming practice and advocacy", "children": [{"id": "e238dc1f-0a96-44d5-8f00-ffd25a6d68e2", "type": "concept", "title": "Names, pronouns, forms, facilities, records, and confidentiality"}, {"id": "e1258c34-8ca1-4014-a9c7-2ba3a9a88f24", "type": "concept", "title": "Family support and chosen family"}, {"id": "256087be-62b2-473c-8301-e334198b3f1c", "type": "concept", "title": "Affirming health, school, housing, and child-welfare practice"}], "description": "Builds concrete skills for respectful services and policy environments."}]}, {"id": "bfe632b8-5b02-40a1-af98-6df85878f566", "type": "topic", "title": "Ableism, Disability Justice, and Neurodiversity", "description": "Students learn to view disability through rights, access, and interdependence—not solely diagnosis or impairment. Disability justice adds an intersectional movement framework led by disabled people.", "children": [{"id": "f1da370b-7626-4a31-80fd-a3ca0ac05853", "type": "subtopic", "title": "Models of disability", "children": [{"id": "4556ba9e-db62-4ea5-9208-d319717a71cd", "type": "concept", "title": "Medical, social, biopsychosocial, human-rights, and disability-justice models"}, {"id": "2e7dda4e-6bae-4684-97ce-968539d781cc", "type": "concept", "title": "Impairment, disability, access needs, and environmental barriers"}, {"id": "8b11e7cb-61fd-4a75-aa23-9136102d88cd", "type": "concept", "title": "Neurodiversity and mad/psychiatric survivor perspectives"}], "description": "Compares frameworks and shows how each changes assessment, goals, and intervention."}, {"id": "3fdbb3df-baa5-47b6-b53e-cdf364bd5a05", "type": "subtopic", "title": "Ableism and exclusion", "children": [{"id": "7f120176-3df6-4f97-81ee-dda791c22b8c", "type": "concept", "title": "Sanism, audism, eugenics, institutionalization, and guardianship"}, {"id": "f91f1236-478d-45b8-a1cb-eff5d43cc399", "type": "concept", "title": "Inspiration, pity, infantilization, and diagnostic overshadowing"}, {"id": "9763f122-f4cf-4c5e-9298-5402055c237d", "type": "concept", "title": "Poverty, violence, policing, and health inequities"}], "description": "Identifies how assumptions about productivity, normalcy, communication, and capacity shape services and institutions."}, {"id": "5a01fbb9-3716-4c0f-b2ab-1d76e02e7283", "type": "subtopic", "title": "Accessible and anti-ableist practice", "children": [{"id": "51b04b20-6d03-4ea9-a14a-43f48c32007f", "type": "concept", "title": "Universal design and reasonable accommodation"}, {"id": "5f5c3a71-132d-491e-853d-dec016b6dd6f", "type": "concept", "title": "Supported decision-making, autonomy, and dignity of risk"}, {"id": "0bb1ebdf-2090-4087-abc7-145526740bbf", "type": "concept", "title": "Accessible communication, technology, meetings, and emergency planning"}], "description": "Turns inclusion into specific design and relationship practices."}]}, {"id": "056205cb-5831-459a-88e7-df820e67cf48", "type": "topic", "title": "Classism, Poverty, and Economic Justice", "description": "This section reframes poverty as a product of political and economic arrangements as well as individual circumstances. Students examine how class shapes opportunity, service encounters, and professional judgments.", "children": [{"id": "2a3df243-4d9f-4bcc-b6ae-278230e19268", "type": "subtopic", "title": "Social class and classism", "children": [{"id": "f85c7b04-80ec-4f06-8eb9-eac34847e201", "type": "concept", "title": "Income, wealth, debt, occupation, education, and status"}, {"id": "b67155a7-4a1d-4282-958d-d6a1fd932a65", "type": "concept", "title": "Class cultures, respectability, and stigma"}, {"id": "ae7b8879-c964-4d48-a616-310ebcc21603", "type": "concept", "title": "Professional-class norms in helping systems"}], "description": "Explores class identity, status, wealth, power, and cultural capital without equating income with worth."}, {"id": "d0e05936-a729-4406-a2f6-0cc884d16de2", "type": "subtopic", "title": "Political economy of inequality", "children": [{"id": "78cd772e-382b-40d5-9a04-03605966883b", "type": "concept", "title": "Wages, precarity, unemployment, and care work"}, {"id": "50169c29-6457-4dcc-b96c-bb51d7be5179", "type": "concept", "title": "Wealth inequality, inheritance, debt, and asset stripping"}, {"id": "4acec51a-3dff-4954-b82a-ac2ac849f3e1", "type": "concept", "title": "Austerity, privatization, and the social safety net"}], "description": "Connects household hardship to labor markets, taxation, housing, social protection, and racialized wealth accumulation."}, {"id": "7a7ab987-8b45-48df-b2a9-33f33254887f", "type": "subtopic", "title": "Economic justice practice", "children": [{"id": "f84ecf14-ae66-4f89-a0a4-b16dab6a5c1b", "type": "concept", "title": "Benefits access, financial capability, and material supports"}, {"id": "2e7d7d8e-f18d-4d60-a4e0-091f5229399f", "type": "concept", "title": "Living wages, housing justice, labor rights, and income guarantees"}, {"id": "83be0f9b-a6ce-4002-96f8-ec086743dc28", "type": "concept", "title": "Mutual aid, cooperatives, and community wealth building"}], "description": "Develops non-stigmatizing direct practice alongside organizational and policy strategies."}]}, {"id": "2a66bfc2-3a18-477c-b00d-f6e88d147f0e", "type": "topic", "title": "Religion, Spirituality, and Religious Oppression", "description": "Students examine religion and spirituality as possible sources of identity, community, meaning, conflict, and harm. The goal is ethically responsive practice without endorsement, avoidance, or stereotyping.", "children": [{"id": "a8c41d31-4b16-4c2c-85cb-4a1aeab993c7", "type": "subtopic", "title": "Religious and spiritual diversity", "children": [{"id": "b4157e2d-b9af-44b9-a2c9-fdfdcd60d008", "type": "concept", "title": "Religion, spirituality, secularity, atheism, and humanism"}, {"id": "3069c5eb-44f0-4dcd-8673-663146be5e08", "type": "concept", "title": "Intrafaith diversity, conversion, observance, and syncretism"}, {"id": "ae48aa79-d54c-442b-8af0-07ac8766ef2a", "type": "concept", "title": "Spiritual strengths, struggle, trauma, and healing"}], "description": "Builds literacy across traditions while preserving client self-definition and recognizing nonreligious worldviews."}, {"id": "2c784279-d42f-4ccc-a362-95f4b8865480", "type": "subtopic", "title": "Religious privilege and oppression", "children": [{"id": "6af79a78-b50d-4a59-84fb-3a6749c86e01", "type": "concept", "title": "Antisemitism, Islamophobia, anti-Sikh hate, and persecution of minority traditions"}, {"id": "ba6b2cb4-739c-4673-96c6-fb8419163c4f", "type": "concept", "title": "Christian normativity and church–state tensions"}, {"id": "cfe34f2b-d131-41a0-949b-3fbf65acde9a", "type": "concept", "title": "Religious nationalism, caste, and communal violence"}], "description": "Analyzes how institutions privilege some traditions and marginalize others."}, {"id": "42547a4b-a4ff-45f5-89a1-69cde20344b5", "type": "subtopic", "title": "Ethical spiritual assessment", "children": [{"id": "fb78ad9f-38d0-4eed-99e2-6e7b9ee68828", "type": "concept", "title": "Consent-based spiritual history and assessment"}, {"id": "532705ca-fea3-473d-8503-940d177c95ff", "type": "concept", "title": "Accommodation, dietary needs, dress, time, and space"}, {"id": "c7a3194f-7afa-4d02-9154-ad236058f72e", "type": "concept", "title": "Referral, collaboration, and avoiding proselytization"}], "description": "Prepares students to discuss spirituality when relevant while honoring boundaries and self-determination."}]}, {"id": "3d1e1fea-b264-4884-8521-81f6d63fa4fd", "type": "topic", "title": "Migration, Nationality, Language, and Xenophobia", "description": "This section examines mobility, borders, citizenship, and language as social determinants. Students practice with migrants and refugees through rights-based, trauma-responsive, and non-assimilationist approaches.", "children": [{"id": "3509bdca-f868-4daa-b2c5-3ca9ee62ac03", "type": "subtopic", "title": "Migration and displacement", "children": [{"id": "1b59eb39-54d8-4329-b62e-11eaec72316d", "type": "concept", "title": "Immigrants, refugees, asylum seekers, temporary residents, undocumented people, and internally displaced persons"}, {"id": "6e85ef81-9f7f-4253-8928-6ae2daeeee9a", "type": "concept", "title": "Forced migration, trafficking, climate displacement, and family separation"}, {"id": "2b8c6c2e-aad3-4c98-9d73-699c10edb56c", "type": "concept", "title": "Transnational families, remittances, and diasporic ties"}], "description": "Differentiates migration pathways and centers the political, economic, environmental, and family contexts of movement."}, {"id": "e8bbf2b5-0111-4e49-a4c1-719ce47adfa8", "type": "subtopic", "title": "Xenophobia and legal precarity", "children": [{"id": "ffc53b18-0a59-4dc3-bd9b-d8a6738a8ccb", "type": "concept", "title": "Citizenship privilege, nativism, detention, and deportability"}, {"id": "93058320-bca9-47f3-bc15-9664050b9e8e", "type": "concept", "title": "Labor exploitation and service exclusions"}, {"id": "bcf0def6-851a-4c2b-9d1b-1c781e92aa18", "type": "concept", "title": "Documentation risk, confidentiality, and public-charge fears"}], "description": "Shows how status and national-origin hierarchies influence safety, eligibility, work, health, and surveillance."}, {"id": "0ad47ca9-1701-4fbe-8181-1b79c9d45dfe", "type": "subtopic", "title": "Language justice and responsive practice", "children": [{"id": "d274c749-8cf4-4e46-bc8b-8eac33978231", "type": "concept", "title": "Professional interpretation and translated materials"}, {"id": "26dad3f2-d0c7-4543-8b44-fd15a8dd42d2", "type": "concept", "title": "Linguicism, accent bias, and literacy"}, {"id": "089a9bf9-c443-4b91-99b7-3e4ccce12b2a", "type": "concept", "title": "Culturally responsive, trauma-informed, and community-partnered services"}], "description": "Treats communication access as a right and language diversity as an asset."}]}, {"id": "0765a030-16e0-4ced-9592-a65d24f0fdb0", "type": "topic", "title": "Ageism and Justice Across the Life Course", "description": "Students analyze how age-based power affects children, youth, adults, and older people. A life-course lens connects present conditions to historical timing, transitions, and accumulated advantage or disadvantage.", "children": [{"id": "4703b665-1be2-41a5-8328-56805422dd54", "type": "subtopic", "title": "Ageism and adultism", "children": [{"id": "e2fddbf7-2e4b-4e47-b957-f3faa8a9d5b4", "type": "concept", "title": "Adultism and children’s participation rights"}, {"id": "33d25b28-0367-4fb5-80e6-46ba7c90ebc9", "type": "concept", "title": "Ageism in work, health care, media, and social services"}, {"id": "f297ebfc-9f52-4eb2-80ff-8c3dbe7ffd64", "type": "concept", "title": "Age norms, dependency narratives, and intergenerational tension"}], "description": "Makes visible age-based stereotypes and the unequal authority attached to adulthood, youth, and later life."}, {"id": "9fb19701-8de1-4d25-a2b2-9f1a2c6f98eb", "type": "subtopic", "title": "Life-course and cohort perspectives", "children": [{"id": "8d3b972a-aa0d-46cf-9c65-96ec8a6b4744", "type": "concept", "title": "Cohort, period, and life-stage effects"}, {"id": "f16ccb48-c557-45d4-9e84-d44764d3933a", "type": "concept", "title": "Transitions, turning points, linked lives, and cumulative inequality"}, {"id": "7f7abfb2-12e5-406e-80b3-6371f1ff9c94", "type": "concept", "title": "Longevity, caregiving, retirement, and changing family forms"}], "description": "Helps students interpret development in social and historical context rather than treating age as a universal experience."}, {"id": "8747c43b-fbd5-43ef-8e04-27de2a61bdf6", "type": "subtopic", "title": "Age-inclusive practice", "children": [{"id": "7ef634a3-6512-4196-b012-d003a8c1faf6", "type": "concept", "title": "Supported decision-making and capacity"}, {"id": "76f69a56-5dc7-4498-bd03-66d7ea577ffe", "type": "concept", "title": "Child/youth participation and elder self-determination"}, {"id": "d1197eda-2122-4698-b385-17c106c21c82", "type": "concept", "title": "Intergenerational programs and age-friendly communities"}], "description": "Builds capacity to balance protection, participation, autonomy, and relational care."}]}, {"id": "e8fca8f6-5614-4958-bb01-9dc3363a4869", "type": "topic", "title": "Environmental, Spatial, and Digital Justice", "description": "Justice increasingly depends on where people live and whether they can access safe environments and essential technologies. This section connects ecological, geographic, and digital conditions to social-work practice.", "children": [{"id": "a7d77938-5b77-4497-88a0-993b28ee9604", "type": "subtopic", "title": "Environmental and climate justice", "children": [{"id": "29441afb-ddac-4b54-9302-7252a3a0d79f", "type": "concept", "title": "Environmental racism and cumulative exposure"}, {"id": "1beaa66d-3789-4afe-a10e-2c6188557075", "type": "concept", "title": "Climate disasters, heat, food/water insecurity, and displacement"}, {"id": "70624e0b-94a1-4efa-87b2-5df6630afe5a", "type": "concept", "title": "Just transition, energy justice, and Indigenous environmental stewardship"}], "description": "Shows why environmental hazards and climate impacts are distributed through race, class, colonialism, and political power."}, {"id": "9327262e-fff8-44c8-8ab3-c4f05e0d3b05", "type": "subtopic", "title": "Place and spatial inequality", "children": [{"id": "de7da2c1-4a4c-4d9b-a9b1-b71d75fb9188", "type": "concept", "title": "Urban, rural, remote, reservation, and border contexts"}, {"id": "f8d94f08-ff8e-431c-8548-d0d37af16344", "type": "concept", "title": "Housing segregation, transportation, food access, and service deserts"}, {"id": "a5e7acee-f991-4f14-85b4-f32987f5b26d", "type": "concept", "title": "Gentrification, displacement, carcerality, and public space"}], "description": "Examines how geography structures services, mobility, belonging, and opportunity."}, {"id": "962bad18-9c8b-45eb-aa00-98510855b990", "type": "subtopic", "title": "Digital inequality and algorithmic oppression", "children": [{"id": "d8545818-cfe5-40c4-8bd8-b8e61c7a25c3", "type": "concept", "title": "Devices, connectivity, affordability, accessibility, and digital literacy"}, {"id": "ba8c3c92-2c36-447a-b524-24cbfd4bd451", "type": "concept", "title": "Automated eligibility, risk scoring, facial recognition, and bias"}, {"id": "a233aec4-0bd2-47d8-b3ef-f2a12b5560ea", "type": "concept", "title": "Privacy, surveillance, data rights, and technology-mediated practice"}], "description": "Prepares students to assess both access barriers and harms created by data-driven systems."}]}, {"id": "117e7037-dc0c-4b9b-8698-70f06c91c88e", "type": "topic", "title": "Cultural Humility, Critical Reflexivity, and Ethical Use of Self", "description": "This section turns inward without making social justice merely personal. Students examine how their social location, emotions, knowledge, and professional authority shape relationships and decisions.", "children": [{"id": "8cb59747-d528-4223-aa62-1a7dbd6a3c23", "type": "subtopic", "title": "Cultural humility", "children": [{"id": "0997666a-0e5e-41b3-bedf-876fa6df97da", "type": "concept", "title": "Lifelong learning and self-critique"}, {"id": "5f9e4b31-f0cc-450a-a12a-df07044bff80", "type": "concept", "title": "Redressing power imbalances"}, {"id": "92d19531-ece0-4a92-abc0-62f6d1b51441", "type": "concept", "title": "Institutional accountability and mutually beneficial partnership"}], "description": "Frames learning as lifelong self-evaluation and power balancing rather than mastery of other people’s cultures."}, {"id": "9f930555-5f0e-4dfe-bc2a-8a9bf1251909", "type": "subtopic", "title": "Positionality and critical reflexivity", "children": [{"id": "1bee07d1-4e50-4caf-8af6-71c4efc6231a", "type": "concept", "title": "Positionality statements and social-location mapping"}, {"id": "8c40d073-6e64-4cc3-8584-982593f59094", "type": "concept", "title": "Bias, defensiveness, shame, guilt, fragility, and moral courage"}, {"id": "17974749-8de8-4b00-8242-7585234b8521", "type": "concept", "title": "Countertransference, use of self, and reflective supervision"}], "description": "Develops disciplined reflection on how standpoint, assumptions, and institutional roles affect what practitioners notice and do."}, {"id": "ed2e8094-d741-4cd5-be06-e53ba36dbbcf", "type": "subtopic", "title": "Ethics, boundaries, and epistemic justice", "children": [{"id": "a2de91f9-cee6-4162-99ac-a65384fc5dde", "type": "concept", "title": "Self-determination, informed consent, privacy, and mandated authority"}, {"id": "9ee3a038-bf8a-4b16-be2c-ee37ae5c2df2", "type": "concept", "title": "Testimonial and hermeneutical injustice"}, {"id": "adf56a0e-4151-4034-a84a-fdf2526e3c14", "type": "concept", "title": "Ethical tensions, accountability, repair, and professional self-care"}], "description": "Connects humility to professional obligations around consent, authority, confidentiality, and whose knowledge counts."}]}, {"id": "a0baefca-662c-4f86-9a23-905612a61142", "type": "topic", "title": "Anti-Oppressive Practice, Solidarity, and Social Change", "description": "The final section integrates course learning into action at micro, mezzo, and macro levels. Students learn to work with—not simply for—people affected by injustice and to evaluate whether change efforts redistribute power.", "children": [{"id": "ac56bb53-c6c8-4b09-b389-c91c7594aeb6", "type": "subtopic", "title": "Anti-oppressive and rights-based practice", "children": [{"id": "c8fbf24f-c98d-4a26-ba39-5f40865448cb", "type": "concept", "title": "Anti-oppressive, structural, critical, feminist, and human-rights approaches"}, {"id": "44bee710-b70e-4c16-b796-8f03cbf9acdf", "type": "concept", "title": "Strengths, empowerment, healing-centered, and trauma-responsive practice"}, {"id": "54a23eac-30b3-4d65-84d6-68022ee1d572", "type": "concept", "title": "Micro–mezzo–macro integration and person-in-environment analysis"}], "description": "Provides frameworks for linking immediate needs to structural causes while preserving dignity, choice, and accountability."}, {"id": "84edc38f-95db-441d-a9ef-58a0c31ed494", "type": "subtopic", "title": "Allyship, solidarity, and accountable partnership", "children": [{"id": "09fdfa54-03f3-4f6b-a943-5b14d3917db5", "type": "concept", "title": "Allyship versus performativity; accompliceship and solidarity"}, {"id": "7b677a88-2615-44f4-ba32-75ddeca6ba85", "type": "concept", "title": "Centering lived expertise and compensating community knowledge"}, {"id": "ef02d7ce-78fd-4936-b5c5-c74ec780871f", "type": "concept", "title": "Coalition building, conflict, accountability, and repair"}], "description": "Distinguishes identity claims from sustained practices that accept guidance, risk, correction, and responsibility."}, {"id": "524f7f9c-4225-4471-b715-e0e801da3440", "type": "subtopic", "title": "Advocacy and policy practice", "children": [{"id": "4b61e529-1a19-4941-95ef-a7a92537ee48", "type": "concept", "title": "Power mapping, stakeholder analysis, and theory of change"}, {"id": "5b1c7f5f-80d7-4042-9985-80aef222788b", "type": "concept", "title": "Direct action, legislative advocacy, administrative advocacy, litigation, and communications"}, {"id": "279d3035-ceb9-4aeb-be3d-6d32edbe60b3", "type": "concept", "title": "Participatory research, narrative change, and budget advocacy"}], "description": "Equips students to choose strategies matched to power, targets, evidence, and community priorities."}, {"id": "77060b29-daa1-487f-8cc5-9ac7e5de1fa7", "type": "subtopic", "title": "Evaluation and sustainable praxis", "children": [{"id": "8833abfb-3146-4dcd-84d9-bdd17eeb85a5", "type": "concept", "title": "Process, outcome, equity, and participatory evaluation"}, {"id": "51329641-a278-47d8-bfba-eda300ef9f8b", "type": "concept", "title": "Disaggregated outcomes and community-defined success"}, {"id": "f1c432b4-73f3-4c16-bf9e-a42b04465229", "type": "concept", "title": "Reflect–act–evaluate cycles, burnout prevention, and sustaining movements"}], "description": "Makes justice work iterative by asking what changed, for whom, at what cost, and with what unintended effects."}]}], "dbBacked": true}$dosjjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'diversity-oppression-and-social-justice'
);

update public.learning_paths
set
  title = 'Diversity, Oppression, and Social Justice',
  goal = 'Diversity, Oppression, and Social Justice',
  summary = 'This course examines diversity, power, privilege, oppression, resistance, and liberation as central concerns of generalist social work. Using intersectional, anti-racist, anti-oppressive, decolonizing, disability-justice, feminist, queer, human-rights, and environmental-justice lenses, students analyze how identities and social locations are shaped by institutions, histories, policies, and everyday relationships. Through critical reflection, case analysis, dialogue, community knowledge, and applied advocacy, students build the humility and practical skill to engage difference, challenge injustice, share power, and pursue accountable change with individuals, families, groups, organizations, and communities.',
  data = $dosjjson${"slug": "diversity-oppression-and-social-justice", "title": "Diversity, Oppression, and Social Justice", "description": "This course examines diversity, power, privilege, oppression, resistance, and liberation as central concerns of generalist social work. Using intersectional, anti-racist, anti-oppressive, decolonizing, disability-justice, feminist, queer, human-rights, and environmental-justice lenses, students analyze how identities and social locations are shaped by institutions, histories, policies, and everyday relationships. Through critical reflection, case analysis, dialogue, community knowledge, and applied advocacy, students build the humility and practical skill to engage difference, challenge injustice, share power, and pursue accountable change with individuals, families, groups, organizations, and communities.", "topics": [{"id": "a5f8e381-8801-406e-9372-7e0173bfe4e4", "type": "topic", "title": "Foundations: Diversity, Identity, and Social Location", "description": "This opening section establishes a shared vocabulary for studying difference without reducing people to categories. Students learn to connect identity, culture, history, and context to social-work relationships and decisions.", "children": [{"id": "290115c1-6c86-469d-a8a7-60c34c92c717", "type": "subtopic", "title": "Diversity and difference", "children": [{"id": "50532e0f-3e85-42e1-b0f4-4d87d7ae60b9", "type": "concept", "title": "Dimensions of diversity: race, ethnicity, culture, class, gender, sexuality, disability, age, religion, nationality, language, and political belief"}, {"id": "a2759d4c-581c-4a72-8b5b-a5ad2c1191bf", "type": "concept", "title": "Within-group diversity and the limits of categorical thinking"}, {"id": "0f6474ca-290e-4fd9-ab89-aaec1c79b643", "type": "concept", "title": "Difference as a source of knowledge, resilience, and collective strength"}], "description": "Clarifies what diversity includes, why difference is socially meaningful, and how a strengths-based approach avoids treating dominant-group experience as universal."}, {"id": "9b62d514-2b64-4f0b-8c56-f6c76b1fd783", "type": "subtopic", "title": "Social identity and social location", "children": [{"id": "a2fccfb2-7f1e-4829-9ee4-d21c83659c37", "type": "concept", "title": "Personal, relational, collective, and professional identities"}, {"id": "de316621-02eb-4cd6-8503-a11b51e3eb4e", "type": "concept", "title": "Ascribed and achieved identities; visibility and disclosure"}, {"id": "e24af25f-bd68-4b56-b8b3-d2ae8ac72a16", "type": "concept", "title": "Context-dependent salience and identity development"}], "description": "Helps students map how identities are lived within relationships and institutions, including identities that are chosen, assigned, visible, concealed, or changing."}, {"id": "13caad86-8f3e-4cf1-ac34-3b43da69a8ea", "type": "subtopic", "title": "Culture, worldview, and meaning", "children": [{"id": "19bfcee4-1861-4453-8bb2-e77e4658ea7c", "type": "concept", "title": "Culture as dynamic, contested, and adaptive"}, {"id": "71e7f362-2450-427a-bf3a-93ae5ea02b0f", "type": "concept", "title": "Worldviews, values, kinship, spirituality, and healing traditions"}, {"id": "b6c4257a-8374-438f-9f93-6e087ecea642", "type": "concept", "title": "Acculturation, biculturalism, code-switching, and cultural continuity"}], "description": "Builds skill in asking how communities make meaning while resisting stereotypes and cultural essentialism."}]}, {"id": "4fb030ef-0aef-4090-b620-3556e5b9116a", "type": "topic", "title": "Power, Privilege, Oppression, and Liberation", "description": "This section supplies the structural lens for the course. Students move beyond prejudice as an individual attitude to examine how power organizes access, risk, voice, and life chances—and how people resist and transform oppressive arrangements.", "children": [{"id": "ebd6eae8-cd75-4fae-93a9-8d312373b68d", "type": "subtopic", "title": "Power and privilege", "children": [{"id": "bf65686e-e2c9-4c15-a3b3-43948f11ff44", "type": "concept", "title": "Power over, power with, power to, and power within"}, {"id": "a3caacc3-9933-4678-b1bb-87a3fcc737a3", "type": "concept", "title": "Unearned advantage, entitlement, and dominant-group norms"}, {"id": "7cc4374d-22c4-4acb-b224-ae5990022d62", "type": "concept", "title": "Gatekeeping, professional authority, and resource control"}], "description": "Shows how power operates through resources, authority, legitimacy, and agenda setting, including benefits that can be unearned and difficult to see from advantaged positions."}, {"id": "1c3d4a1e-2f90-4d08-a60e-8a05bebf3269", "type": "subtopic", "title": "Levels and mechanisms of oppression", "children": [{"id": "53379122-a070-4574-be6e-3f020a16264e", "type": "concept", "title": "Internalized, interpersonal, institutional, and structural oppression"}, {"id": "a61c602d-137b-46e4-8490-962feb365bcd", "type": "concept", "title": "Ideology, policy, routine practice, and cumulative disadvantage"}, {"id": "c012a8f3-4130-433c-a7b3-311b60a13ac1", "type": "concept", "title": "Segregation, surveillance, exclusion, extraction, and erasure"}], "description": "Distinguishes interpersonal harm from institutional and structural patterns so interventions can target the level producing the problem."}, {"id": "814de2d8-7191-4eb1-a537-11b2352dd358", "type": "subtopic", "title": "Resistance and liberation", "children": [{"id": "3e500eea-06ba-4887-8094-b7f492f8304e", "type": "concept", "title": "Everyday resistance, mutual aid, organizing, and movement building"}, {"id": "9cb3f8b9-0b36-49ef-8aa2-5a6623e6f546", "type": "concept", "title": "Liberatory consciousness and collective efficacy"}, {"id": "00b152c4-b588-464c-a3d9-51b35b594f8b", "type": "concept", "title": "Restoration, reparation, redistribution, recognition, and representation"}], "description": "Centers agency and collective action rather than portraying oppressed communities only through harm or deficit."}]}, {"id": "453ac892-91c9-45f0-89aa-8df426efab4a", "type": "topic", "title": "Intersectionality and Multiple Systems of Inequality", "description": "Intersectionality helps students analyze how systems of power combine to create experiences that cannot be understood by adding single identities together. It is both an analytic lens and a guide to more precise practice.", "children": [{"id": "605e5cdc-3fb9-4b8b-8651-c8f730be1cc3", "type": "subtopic", "title": "Origins and core claims", "children": [{"id": "9d45034e-8a0a-4ccc-b5bd-ec7d4f50ed1b", "type": "concept", "title": "Black feminist thought and the Combahee River Collective"}, {"id": "60f5cfed-dfd0-448a-aa17-38fdabaad475", "type": "concept", "title": "Crenshaw’s structural, political, and representational intersectionality"}, {"id": "ffbfd3e8-3aae-48da-9ca7-1dbaa2bbbcaf", "type": "concept", "title": "Avoiding “identity checklist” versions of intersectionality"}], "description": "Introduces the Black feminist roots of intersectionality and its focus on power, institutional failure, and people erased by single-axis frameworks."}, {"id": "93b8e7f8-88cd-455e-86e5-38758899c7c1", "type": "subtopic", "title": "Intersecting systems in lived experience", "children": [{"id": "b271f203-37d1-4774-8259-79aac9c18917", "type": "concept", "title": "Race–class–gender–disability intersections"}, {"id": "c4ce6ae0-d24d-4989-ad69-2b45f3734c0e", "type": "concept", "title": "Cumulative advantage and disadvantage across the life course"}, {"id": "8e9a43ed-9feb-4ba8-90ff-e2c168daa1d1", "type": "concept", "title": "Within-group differences and intragroup power"}], "description": "Develops contextual analysis of how social locations change exposure to risk, access to services, and treatment by institutions."}, {"id": "680ab2cd-92d2-4259-bc65-985c6b2ca3dc", "type": "subtopic", "title": "Intersectional assessment and policy analysis", "children": [{"id": "13b0ff64-c97d-4df1-885b-73045173fc02", "type": "concept", "title": "Disaggregated and community-defined data"}, {"id": "75479a13-92ba-41de-8007-3f631330afc7", "type": "concept", "title": "Universal design versus targeted universalism"}, {"id": "7589cc7c-1e6e-46c9-b0a8-70318ef44882", "type": "concept", "title": "Unintended consequences and distributional impact"}], "description": "Translates theory into questions, data practices, and policy evaluation that reveal who benefits, who is burdened, and who is missing."}]}, {"id": "ed4565d8-47a1-481f-9925-e7808ccb59ae", "type": "topic", "title": "Racism, Racialization, Colonialism, and Indigenous Sovereignty", "description": "This section examines racism as a historical and contemporary system, not merely personal bias. It also addresses settler colonialism and Indigenous rights so anti-racist practice includes sovereignty, land, and self-determination.", "children": [{"id": "0c8c11b1-2032-42bf-bb30-ac2b31faa602", "type": "subtopic", "title": "Race and racialization", "children": [{"id": "0f80ee21-9d02-43f7-98ec-54881cd2e335", "type": "concept", "title": "Social construction of race and racial formation"}, {"id": "4770fb1d-dded-4aa9-a87b-afaea5f6d510", "type": "concept", "title": "Whiteness, colorism, anti-Blackness, and model-minority narratives"}, {"id": "8d717791-1259-4273-be6f-806fcd0e5487", "type": "concept", "title": "Implicit bias, explicit bias, microaggressions, and racial trauma"}], "description": "Explains race as a changing social and political classification with material consequences."}, {"id": "f0c95517-08e8-4502-ae92-910f511d85fd", "type": "subtopic", "title": "Structural and institutional racism", "children": [{"id": "c2f660e2-a67b-4b73-905a-f91006c37e21", "type": "concept", "title": "Housing, education, health, child welfare, immigration, and criminal legal systems"}, {"id": "6c91cc77-620c-4e56-926a-5556fda8d839", "type": "concept", "title": "Redlining, segregation, wealth extraction, and cumulative harm"}, {"id": "04401c41-aaf8-473c-a1fb-3f16b178ab14", "type": "concept", "title": "Disparity, disproportionality, discrimination, and causal inference"}], "description": "Links historical policies to current disparities without treating inequity as proof of group deficiency."}, {"id": "0eb7f8d2-cf67-421a-a918-7e0e3b073a8a", "type": "subtopic", "title": "Settler colonialism and Indigenous sovereignty", "children": [{"id": "d5d079bc-93b0-42a3-8940-4cd9e356d213", "type": "concept", "title": "Land, treaties, sovereignty, and self-determination"}, {"id": "446d7d89-ba41-4273-bf2b-53dd35153b10", "type": "concept", "title": "Forced removal, residential/boarding schools, child removal, and cultural suppression"}, {"id": "da7b1492-729f-47ef-b5c3-a4054d4d7836", "type": "concept", "title": "Decolonizing practice, rematriation, and community-led healing"}], "description": "Builds respect for Indigenous peoples as contemporary political communities with inherent rights, knowledge systems, and authority."}, {"id": "165510ad-f841-47b5-a8c7-5addc7e18e1e", "type": "subtopic", "title": "Anti-racist and decolonizing practice", "children": [{"id": "9382be6a-69f4-4b59-9438-91d837e124a9", "type": "concept", "title": "Racial equity impact assessment"}, {"id": "42714683-872c-4992-ae33-2ac606ba54fc", "type": "concept", "title": "Power sharing, reparative approaches, and institutional accountability"}, {"id": "66a12574-8896-4016-a6c3-062fc294a8cb", "type": "concept", "title": "Community-defined evidence and Indigenous data sovereignty"}], "description": "Moves from awareness to accountable action in relationships, organizations, policy, and research."}]}, {"id": "40429b5c-7341-4082-959a-9c3e8e001728", "type": "topic", "title": "Sexism, Patriarchy, and Gender Justice", "description": "Students investigate how gender is socially organized and how sexism interacts with race, class, disability, sexuality, and nationality. The focus is gender justice in everyday practice and institutions.", "children": [{"id": "36cfc7d2-2829-4fda-9abe-f8a1a23ed06f", "type": "subtopic", "title": "Gender as a social system", "children": [{"id": "f5dc6a7a-bf92-49c0-85bf-2403736ddeaf", "type": "concept", "title": "Gender socialization and the gender binary"}, {"id": "78054c05-8a05-43fb-82fc-f656ec5ae269", "type": "concept", "title": "Patriarchy, cisnormativity, and hegemonic masculinity"}, {"id": "4f84c2c8-20a3-4dc3-a74e-324184acb0da", "type": "concept", "title": "Gender diversity across cultures and histories"}], "description": "Separates sex characteristics, gender identity, gender expression, and social roles while examining how institutions enforce gender norms."}, {"id": "501894c6-d5cd-40df-baca-c5b07d8424a0", "type": "subtopic", "title": "Gendered inequality and violence", "children": [{"id": "d611c149-3dcc-4beb-a4f6-e7a955eb3e4c", "type": "concept", "title": "Paid work, unpaid care, occupational segregation, and economic insecurity"}, {"id": "98ad1cb8-c838-458f-8df9-4a1f64f232ef", "type": "concept", "title": "Reproductive justice and bodily autonomy"}, {"id": "882db92e-6b87-4a57-822a-b6e897dce19c", "type": "concept", "title": "Gender-based violence, coercive control, and institutional betrayal"}], "description": "Connects private experience to structural conditions and highlights survivor-centered, non-carceral possibilities."}, {"id": "500002eb-b61b-4635-9523-d60e429110c9", "type": "subtopic", "title": "Gender-responsive practice", "children": [{"id": "e8ede4eb-8983-4be0-8359-72c12ac3cdec", "type": "concept", "title": "Survivor-centered and trauma-informed engagement"}, {"id": "7c23b96b-a07c-4374-b927-20311f0a3f8a", "type": "concept", "title": "Inclusive assessment and documentation"}, {"id": "aca20ab4-7f64-4106-9fa6-a59733a33823", "type": "concept", "title": "Policy advocacy for care, safety, pay equity, and reproductive freedom"}], "description": "Develops approaches that affirm agency, safety, and self-definition without stereotyping clients."}]}, {"id": "f816501b-7900-4a39-96fd-5ba0a479811c", "type": "topic", "title": "Sexuality, Gender Diversity, and LGBTQIA2S+ Justice", "description": "This section prepares students to challenge heterosexism and cisnormativity while providing affirming, developmentally appropriate, and context-sensitive support across the life course.", "children": [{"id": "13c96aef-369e-41aa-94cc-8c455c475193", "type": "subtopic", "title": "Sexual orientation and gender diversity", "children": [{"id": "bec113fb-f760-4065-b2f2-0cf87c1df2eb", "type": "concept", "title": "Sexual orientation, romantic orientation, gender identity, expression, and sex characteristics"}, {"id": "f614a60e-e280-4a10-a3bb-2b0b2d505e9a", "type": "concept", "title": "LGBTQIA2S+ histories and community diversity"}, {"id": "e8f65ce6-aeeb-4ff4-9bd5-7a8033f3980b", "type": "concept", "title": "Coming out, disclosure, privacy, and safety"}], "description": "Provides accurate language while emphasizing that terminology, identity, and community membership are culturally and historically situated."}, {"id": "e400c28e-86a9-4bea-bb8d-f21bdfd5804c", "type": "subtopic", "title": "Heterosexism, cisnormativity, and minority stress", "children": [{"id": "b3d8fc9f-3b7e-4eb6-b6b9-367f3806e9bc", "type": "concept", "title": "Interpersonal, institutional, and structural stigma"}, {"id": "c7b91556-6336-4f6b-b7ff-29d5461ab51c", "type": "concept", "title": "Minority stress, rejection, concealment, and resilience"}, {"id": "7546f7df-c7b1-499d-a8f6-670a1aaae664", "type": "concept", "title": "Conversion practices, criminalization, and barriers to care"}], "description": "Explains how stigma and hostile environments shape health and social outcomes without pathologizing identity."}, {"id": "7b6049dd-5f36-479a-8727-3ae971c2c90f", "type": "subtopic", "title": "Affirming practice and advocacy", "children": [{"id": "e238dc1f-0a96-44d5-8f00-ffd25a6d68e2", "type": "concept", "title": "Names, pronouns, forms, facilities, records, and confidentiality"}, {"id": "e1258c34-8ca1-4014-a9c7-2ba3a9a88f24", "type": "concept", "title": "Family support and chosen family"}, {"id": "256087be-62b2-473c-8301-e334198b3f1c", "type": "concept", "title": "Affirming health, school, housing, and child-welfare practice"}], "description": "Builds concrete skills for respectful services and policy environments."}]}, {"id": "bfe632b8-5b02-40a1-af98-6df85878f566", "type": "topic", "title": "Ableism, Disability Justice, and Neurodiversity", "description": "Students learn to view disability through rights, access, and interdependence—not solely diagnosis or impairment. Disability justice adds an intersectional movement framework led by disabled people.", "children": [{"id": "f1da370b-7626-4a31-80fd-a3ca0ac05853", "type": "subtopic", "title": "Models of disability", "children": [{"id": "4556ba9e-db62-4ea5-9208-d319717a71cd", "type": "concept", "title": "Medical, social, biopsychosocial, human-rights, and disability-justice models"}, {"id": "2e7dda4e-6bae-4684-97ce-968539d781cc", "type": "concept", "title": "Impairment, disability, access needs, and environmental barriers"}, {"id": "8b11e7cb-61fd-4a75-aa23-9136102d88cd", "type": "concept", "title": "Neurodiversity and mad/psychiatric survivor perspectives"}], "description": "Compares frameworks and shows how each changes assessment, goals, and intervention."}, {"id": "3fdbb3df-baa5-47b6-b53e-cdf364bd5a05", "type": "subtopic", "title": "Ableism and exclusion", "children": [{"id": "7f120176-3df6-4f97-81ee-dda791c22b8c", "type": "concept", "title": "Sanism, audism, eugenics, institutionalization, and guardianship"}, {"id": "f91f1236-478d-45b8-a1cb-eff5d43cc399", "type": "concept", "title": "Inspiration, pity, infantilization, and diagnostic overshadowing"}, {"id": "9763f122-f4cf-4c5e-9298-5402055c237d", "type": "concept", "title": "Poverty, violence, policing, and health inequities"}], "description": "Identifies how assumptions about productivity, normalcy, communication, and capacity shape services and institutions."}, {"id": "5a01fbb9-3716-4c0f-b2ab-1d76e02e7283", "type": "subtopic", "title": "Accessible and anti-ableist practice", "children": [{"id": "51b04b20-6d03-4ea9-a14a-43f48c32007f", "type": "concept", "title": "Universal design and reasonable accommodation"}, {"id": "5f5c3a71-132d-491e-853d-dec016b6dd6f", "type": "concept", "title": "Supported decision-making, autonomy, and dignity of risk"}, {"id": "0bb1ebdf-2090-4087-abc7-145526740bbf", "type": "concept", "title": "Accessible communication, technology, meetings, and emergency planning"}], "description": "Turns inclusion into specific design and relationship practices."}]}, {"id": "056205cb-5831-459a-88e7-df820e67cf48", "type": "topic", "title": "Classism, Poverty, and Economic Justice", "description": "This section reframes poverty as a product of political and economic arrangements as well as individual circumstances. Students examine how class shapes opportunity, service encounters, and professional judgments.", "children": [{"id": "2a3df243-4d9f-4bcc-b6ae-278230e19268", "type": "subtopic", "title": "Social class and classism", "children": [{"id": "f85c7b04-80ec-4f06-8eb9-eac34847e201", "type": "concept", "title": "Income, wealth, debt, occupation, education, and status"}, {"id": "b67155a7-4a1d-4282-958d-d6a1fd932a65", "type": "concept", "title": "Class cultures, respectability, and stigma"}, {"id": "ae7b8879-c964-4d48-a616-310ebcc21603", "type": "concept", "title": "Professional-class norms in helping systems"}], "description": "Explores class identity, status, wealth, power, and cultural capital without equating income with worth."}, {"id": "d0e05936-a729-4406-a2f6-0cc884d16de2", "type": "subtopic", "title": "Political economy of inequality", "children": [{"id": "78cd772e-382b-40d5-9a04-03605966883b", "type": "concept", "title": "Wages, precarity, unemployment, and care work"}, {"id": "50169c29-6457-4dcc-b96c-bb51d7be5179", "type": "concept", "title": "Wealth inequality, inheritance, debt, and asset stripping"}, {"id": "4acec51a-3dff-4954-b82a-ac2ac849f3e1", "type": "concept", "title": "Austerity, privatization, and the social safety net"}], "description": "Connects household hardship to labor markets, taxation, housing, social protection, and racialized wealth accumulation."}, {"id": "7a7ab987-8b45-48df-b2a9-33f33254887f", "type": "subtopic", "title": "Economic justice practice", "children": [{"id": "f84ecf14-ae66-4f89-a0a4-b16dab6a5c1b", "type": "concept", "title": "Benefits access, financial capability, and material supports"}, {"id": "2e7d7d8e-f18d-4d60-a4e0-091f5229399f", "type": "concept", "title": "Living wages, housing justice, labor rights, and income guarantees"}, {"id": "83be0f9b-a6ce-4002-96f8-ec086743dc28", "type": "concept", "title": "Mutual aid, cooperatives, and community wealth building"}], "description": "Develops non-stigmatizing direct practice alongside organizational and policy strategies."}]}, {"id": "2a66bfc2-3a18-477c-b00d-f6e88d147f0e", "type": "topic", "title": "Religion, Spirituality, and Religious Oppression", "description": "Students examine religion and spirituality as possible sources of identity, community, meaning, conflict, and harm. The goal is ethically responsive practice without endorsement, avoidance, or stereotyping.", "children": [{"id": "a8c41d31-4b16-4c2c-85cb-4a1aeab993c7", "type": "subtopic", "title": "Religious and spiritual diversity", "children": [{"id": "b4157e2d-b9af-44b9-a2c9-fdfdcd60d008", "type": "concept", "title": "Religion, spirituality, secularity, atheism, and humanism"}, {"id": "3069c5eb-44f0-4dcd-8673-663146be5e08", "type": "concept", "title": "Intrafaith diversity, conversion, observance, and syncretism"}, {"id": "ae48aa79-d54c-442b-8af0-07ac8766ef2a", "type": "concept", "title": "Spiritual strengths, struggle, trauma, and healing"}], "description": "Builds literacy across traditions while preserving client self-definition and recognizing nonreligious worldviews."}, {"id": "2c784279-d42f-4ccc-a362-95f4b8865480", "type": "subtopic", "title": "Religious privilege and oppression", "children": [{"id": "6af79a78-b50d-4a59-84fb-3a6749c86e01", "type": "concept", "title": "Antisemitism, Islamophobia, anti-Sikh hate, and persecution of minority traditions"}, {"id": "ba6b2cb4-739c-4673-96c6-fb8419163c4f", "type": "concept", "title": "Christian normativity and church–state tensions"}, {"id": "cfe34f2b-d131-41a0-949b-3fbf65acde9a", "type": "concept", "title": "Religious nationalism, caste, and communal violence"}], "description": "Analyzes how institutions privilege some traditions and marginalize others."}, {"id": "42547a4b-a4ff-45f5-89a1-69cde20344b5", "type": "subtopic", "title": "Ethical spiritual assessment", "children": [{"id": "fb78ad9f-38d0-4eed-99e2-6e7b9ee68828", "type": "concept", "title": "Consent-based spiritual history and assessment"}, {"id": "532705ca-fea3-473d-8503-940d177c95ff", "type": "concept", "title": "Accommodation, dietary needs, dress, time, and space"}, {"id": "c7a3194f-7afa-4d02-9154-ad236058f72e", "type": "concept", "title": "Referral, collaboration, and avoiding proselytization"}], "description": "Prepares students to discuss spirituality when relevant while honoring boundaries and self-determination."}]}, {"id": "3d1e1fea-b264-4884-8521-81f6d63fa4fd", "type": "topic", "title": "Migration, Nationality, Language, and Xenophobia", "description": "This section examines mobility, borders, citizenship, and language as social determinants. Students practice with migrants and refugees through rights-based, trauma-responsive, and non-assimilationist approaches.", "children": [{"id": "3509bdca-f868-4daa-b2c5-3ca9ee62ac03", "type": "subtopic", "title": "Migration and displacement", "children": [{"id": "1b59eb39-54d8-4329-b62e-11eaec72316d", "type": "concept", "title": "Immigrants, refugees, asylum seekers, temporary residents, undocumented people, and internally displaced persons"}, {"id": "6e85ef81-9f7f-4253-8928-6ae2daeeee9a", "type": "concept", "title": "Forced migration, trafficking, climate displacement, and family separation"}, {"id": "2b8c6c2e-aad3-4c98-9d73-699c10edb56c", "type": "concept", "title": "Transnational families, remittances, and diasporic ties"}], "description": "Differentiates migration pathways and centers the political, economic, environmental, and family contexts of movement."}, {"id": "e8bbf2b5-0111-4e49-a4c1-719ce47adfa8", "type": "subtopic", "title": "Xenophobia and legal precarity", "children": [{"id": "ffc53b18-0a59-4dc3-bd9b-d8a6738a8ccb", "type": "concept", "title": "Citizenship privilege, nativism, detention, and deportability"}, {"id": "93058320-bca9-47f3-bc15-9664050b9e8e", "type": "concept", "title": "Labor exploitation and service exclusions"}, {"id": "bcf0def6-851a-4c2b-9d1b-1c781e92aa18", "type": "concept", "title": "Documentation risk, confidentiality, and public-charge fears"}], "description": "Shows how status and national-origin hierarchies influence safety, eligibility, work, health, and surveillance."}, {"id": "0ad47ca9-1701-4fbe-8181-1b79c9d45dfe", "type": "subtopic", "title": "Language justice and responsive practice", "children": [{"id": "d274c749-8cf4-4e46-bc8b-8eac33978231", "type": "concept", "title": "Professional interpretation and translated materials"}, {"id": "26dad3f2-d0c7-4543-8b44-fd15a8dd42d2", "type": "concept", "title": "Linguicism, accent bias, and literacy"}, {"id": "089a9bf9-c443-4b91-99b7-3e4ccce12b2a", "type": "concept", "title": "Culturally responsive, trauma-informed, and community-partnered services"}], "description": "Treats communication access as a right and language diversity as an asset."}]}, {"id": "0765a030-16e0-4ced-9592-a65d24f0fdb0", "type": "topic", "title": "Ageism and Justice Across the Life Course", "description": "Students analyze how age-based power affects children, youth, adults, and older people. A life-course lens connects present conditions to historical timing, transitions, and accumulated advantage or disadvantage.", "children": [{"id": "4703b665-1be2-41a5-8328-56805422dd54", "type": "subtopic", "title": "Ageism and adultism", "children": [{"id": "e2fddbf7-2e4b-4e47-b957-f3faa8a9d5b4", "type": "concept", "title": "Adultism and children’s participation rights"}, {"id": "33d25b28-0367-4fb5-80e6-46ba7c90ebc9", "type": "concept", "title": "Ageism in work, health care, media, and social services"}, {"id": "f297ebfc-9f52-4eb2-80ff-8c3dbe7ffd64", "type": "concept", "title": "Age norms, dependency narratives, and intergenerational tension"}], "description": "Makes visible age-based stereotypes and the unequal authority attached to adulthood, youth, and later life."}, {"id": "9fb19701-8de1-4d25-a2b2-9f1a2c6f98eb", "type": "subtopic", "title": "Life-course and cohort perspectives", "children": [{"id": "8d3b972a-aa0d-46cf-9c65-96ec8a6b4744", "type": "concept", "title": "Cohort, period, and life-stage effects"}, {"id": "f16ccb48-c557-45d4-9e84-d44764d3933a", "type": "concept", "title": "Transitions, turning points, linked lives, and cumulative inequality"}, {"id": "7f7abfb2-12e5-406e-80b3-6371f1ff9c94", "type": "concept", "title": "Longevity, caregiving, retirement, and changing family forms"}], "description": "Helps students interpret development in social and historical context rather than treating age as a universal experience."}, {"id": "8747c43b-fbd5-43ef-8e04-27de2a61bdf6", "type": "subtopic", "title": "Age-inclusive practice", "children": [{"id": "7ef634a3-6512-4196-b012-d003a8c1faf6", "type": "concept", "title": "Supported decision-making and capacity"}, {"id": "76f69a56-5dc7-4498-bd03-66d7ea577ffe", "type": "concept", "title": "Child/youth participation and elder self-determination"}, {"id": "d1197eda-2122-4698-b385-17c106c21c82", "type": "concept", "title": "Intergenerational programs and age-friendly communities"}], "description": "Builds capacity to balance protection, participation, autonomy, and relational care."}]}, {"id": "e8fca8f6-5614-4958-bb01-9dc3363a4869", "type": "topic", "title": "Environmental, Spatial, and Digital Justice", "description": "Justice increasingly depends on where people live and whether they can access safe environments and essential technologies. This section connects ecological, geographic, and digital conditions to social-work practice.", "children": [{"id": "a7d77938-5b77-4497-88a0-993b28ee9604", "type": "subtopic", "title": "Environmental and climate justice", "children": [{"id": "29441afb-ddac-4b54-9302-7252a3a0d79f", "type": "concept", "title": "Environmental racism and cumulative exposure"}, {"id": "1beaa66d-3789-4afe-a10e-2c6188557075", "type": "concept", "title": "Climate disasters, heat, food/water insecurity, and displacement"}, {"id": "70624e0b-94a1-4efa-87b2-5df6630afe5a", "type": "concept", "title": "Just transition, energy justice, and Indigenous environmental stewardship"}], "description": "Shows why environmental hazards and climate impacts are distributed through race, class, colonialism, and political power."}, {"id": "9327262e-fff8-44c8-8ab3-c4f05e0d3b05", "type": "subtopic", "title": "Place and spatial inequality", "children": [{"id": "de7da2c1-4a4c-4d9b-a9b1-b71d75fb9188", "type": "concept", "title": "Urban, rural, remote, reservation, and border contexts"}, {"id": "f8d94f08-ff8e-431c-8548-d0d37af16344", "type": "concept", "title": "Housing segregation, transportation, food access, and service deserts"}, {"id": "a5e7acee-f991-4f14-85b4-f32987f5b26d", "type": "concept", "title": "Gentrification, displacement, carcerality, and public space"}], "description": "Examines how geography structures services, mobility, belonging, and opportunity."}, {"id": "962bad18-9c8b-45eb-aa00-98510855b990", "type": "subtopic", "title": "Digital inequality and algorithmic oppression", "children": [{"id": "d8545818-cfe5-40c4-8bd8-b8e61c7a25c3", "type": "concept", "title": "Devices, connectivity, affordability, accessibility, and digital literacy"}, {"id": "ba8c3c92-2c36-447a-b524-24cbfd4bd451", "type": "concept", "title": "Automated eligibility, risk scoring, facial recognition, and bias"}, {"id": "a233aec4-0bd2-47d8-b3ef-f2a12b5560ea", "type": "concept", "title": "Privacy, surveillance, data rights, and technology-mediated practice"}], "description": "Prepares students to assess both access barriers and harms created by data-driven systems."}]}, {"id": "117e7037-dc0c-4b9b-8698-70f06c91c88e", "type": "topic", "title": "Cultural Humility, Critical Reflexivity, and Ethical Use of Self", "description": "This section turns inward without making social justice merely personal. Students examine how their social location, emotions, knowledge, and professional authority shape relationships and decisions.", "children": [{"id": "8cb59747-d528-4223-aa62-1a7dbd6a3c23", "type": "subtopic", "title": "Cultural humility", "children": [{"id": "0997666a-0e5e-41b3-bedf-876fa6df97da", "type": "concept", "title": "Lifelong learning and self-critique"}, {"id": "5f9e4b31-f0cc-450a-a12a-df07044bff80", "type": "concept", "title": "Redressing power imbalances"}, {"id": "92d19531-ece0-4a92-abc0-62f6d1b51441", "type": "concept", "title": "Institutional accountability and mutually beneficial partnership"}], "description": "Frames learning as lifelong self-evaluation and power balancing rather than mastery of other people’s cultures."}, {"id": "9f930555-5f0e-4dfe-bc2a-8a9bf1251909", "type": "subtopic", "title": "Positionality and critical reflexivity", "children": [{"id": "1bee07d1-4e50-4caf-8af6-71c4efc6231a", "type": "concept", "title": "Positionality statements and social-location mapping"}, {"id": "8c40d073-6e64-4cc3-8584-982593f59094", "type": "concept", "title": "Bias, defensiveness, shame, guilt, fragility, and moral courage"}, {"id": "17974749-8de8-4b00-8242-7585234b8521", "type": "concept", "title": "Countertransference, use of self, and reflective supervision"}], "description": "Develops disciplined reflection on how standpoint, assumptions, and institutional roles affect what practitioners notice and do."}, {"id": "ed2e8094-d741-4cd5-be06-e53ba36dbbcf", "type": "subtopic", "title": "Ethics, boundaries, and epistemic justice", "children": [{"id": "a2de91f9-cee6-4162-99ac-a65384fc5dde", "type": "concept", "title": "Self-determination, informed consent, privacy, and mandated authority"}, {"id": "9ee3a038-bf8a-4b16-be2c-ee37ae5c2df2", "type": "concept", "title": "Testimonial and hermeneutical injustice"}, {"id": "adf56a0e-4151-4034-a84a-fdf2526e3c14", "type": "concept", "title": "Ethical tensions, accountability, repair, and professional self-care"}], "description": "Connects humility to professional obligations around consent, authority, confidentiality, and whose knowledge counts."}]}, {"id": "a0baefca-662c-4f86-9a23-905612a61142", "type": "topic", "title": "Anti-Oppressive Practice, Solidarity, and Social Change", "description": "The final section integrates course learning into action at micro, mezzo, and macro levels. Students learn to work with—not simply for—people affected by injustice and to evaluate whether change efforts redistribute power.", "children": [{"id": "ac56bb53-c6c8-4b09-b389-c91c7594aeb6", "type": "subtopic", "title": "Anti-oppressive and rights-based practice", "children": [{"id": "c8fbf24f-c98d-4a26-ba39-5f40865448cb", "type": "concept", "title": "Anti-oppressive, structural, critical, feminist, and human-rights approaches"}, {"id": "44bee710-b70e-4c16-b796-8f03cbf9acdf", "type": "concept", "title": "Strengths, empowerment, healing-centered, and trauma-responsive practice"}, {"id": "54a23eac-30b3-4d65-84d6-68022ee1d572", "type": "concept", "title": "Micro–mezzo–macro integration and person-in-environment analysis"}], "description": "Provides frameworks for linking immediate needs to structural causes while preserving dignity, choice, and accountability."}, {"id": "84edc38f-95db-441d-a9ef-58a0c31ed494", "type": "subtopic", "title": "Allyship, solidarity, and accountable partnership", "children": [{"id": "09fdfa54-03f3-4f6b-a943-5b14d3917db5", "type": "concept", "title": "Allyship versus performativity; accompliceship and solidarity"}, {"id": "7b677a88-2615-44f4-ba32-75ddeca6ba85", "type": "concept", "title": "Centering lived expertise and compensating community knowledge"}, {"id": "ef02d7ce-78fd-4936-b5c5-c74ec780871f", "type": "concept", "title": "Coalition building, conflict, accountability, and repair"}], "description": "Distinguishes identity claims from sustained practices that accept guidance, risk, correction, and responsibility."}, {"id": "524f7f9c-4225-4471-b715-e0e801da3440", "type": "subtopic", "title": "Advocacy and policy practice", "children": [{"id": "4b61e529-1a19-4941-95ef-a7a92537ee48", "type": "concept", "title": "Power mapping, stakeholder analysis, and theory of change"}, {"id": "5b1c7f5f-80d7-4042-9985-80aef222788b", "type": "concept", "title": "Direct action, legislative advocacy, administrative advocacy, litigation, and communications"}, {"id": "279d3035-ceb9-4aeb-be3d-6d32edbe60b3", "type": "concept", "title": "Participatory research, narrative change, and budget advocacy"}], "description": "Equips students to choose strategies matched to power, targets, evidence, and community priorities."}, {"id": "77060b29-daa1-487f-8cc5-9ac7e5de1fa7", "type": "subtopic", "title": "Evaluation and sustainable praxis", "children": [{"id": "8833abfb-3146-4dcd-84d9-bdd17eeb85a5", "type": "concept", "title": "Process, outcome, equity, and participatory evaluation"}, {"id": "51329641-a278-47d8-bfba-eda300ef9f8b", "type": "concept", "title": "Disaggregated outcomes and community-defined success"}, {"id": "f1c432b4-73f3-4c16-bf9e-a42b04465229", "type": "concept", "title": "Reflect–act–evaluate cycles, burnout prevention, and sustaining movements"}], "description": "Makes justice work iterative by asking what changed, for whom, at what cost, and with what unintended effects."}]}], "dbBacked": true}$dosjjson$::jsonb,
